            current_section = stripped[1:-1].strip()
            if current_section not in result:
                result[current_section] = {}
            last_key = None
            continue

        # Handle indentation for continuations
        indent = len(line) - len(line.lstrip())

        # Determine separator
        sep_idx_eq = line.find('=')
        sep_idx_col = line.find(':')

        if sep_idx_eq == -1:
            sep_idx = sep_idx_col
        elif sep_idx_col == -1:
            sep_idx = sep_idx_eq
        else:
            sep_idx = min(sep_idx_eq, sep_idx_col)

        if sep_idx != -1:
            # New key-value pair
            key = line[:sep_idx].strip().lower()
            val = line[sep_idx + 1:].strip()

            if current_section not in result:
                result[current_section] = {}

            result[current_section][key] = val
            last_key = key
            last_indent = indent
        else:
            # No separator: check if it's a continuation
            if last_key is not None and indent > last_indent:
                if current_section not in result:
                    result[current_section] = {}
                result[current_section][last_key] += " " + stripped
