def retry_with_deadline(fn, retry_on, total_deadline, base_delay, clock, sleep, rand):
    start = clock()
    deadline = start + total_deadline
    attempt = 0
    last_exc = None

    while True:
        attempt += 1
        try:
            return fn()
        except retry_on as exc:
            last_exc = exc
        except Exception as exc:
            raise

        # Compute the delay for the next retry (retry number `attempt`, since the first failed call was retry 0, the next is retry 1)
        n = attempt  # the retry number that would follow (first retry is n=1)
        delay = base_delay * (2 ** (n - 1)) * rand()

        # Check if the wait would end at or after the deadline
        if clock() + delay >= deadline:
            raise last_exc
        sleep(delay)
