def parse_ini(text):
    result = {}
    current_section_name = 'DEFAULT'
    last_key = None
    last_indent = 0

    lines = text.splitlines()

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith(';') or stripped.startswith('#'):
            continue

        # Calculate indentation for continuation check
        indent = len(line) - len(line.lstrip())

        # Section header check
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section_name = stripped[1:-1].strip()
            if current_section_name not in result:
                result[current_section_name] = {}
            last_key = None
            last_indent = 0
            continue

        # Check for key-value separators
        sep_idx_eq = line.find('=')
        sep_idx_col = line.find(':')

        # Determine the first occurrence of either separator
        if sep_idx_eq == -1:
            sep_idx = sep_idx_col
        elif sep_idx_col == -1:
            sep_idx = sep_idx_eq
        else:
            sep_idx = min(sep_idx_eq, sep_idx_col)

        if sep_idx != -1:
            # New key-value pair
            key = line[:sep_idx].strip().lower()
            value = line[sep_idx + 1:].strip()

            if current_section_name not in result:
                result[current_section_name] = {}

            result[current_section_name][key] = value
            last_key = key
            last_indent = indent
        else:
            # Potential continuation line
            if last_key is not None and indent > last_indent:
                if current_section_name in result:
                    result[current_section_name][last_key] += " " + stripped
            else:
                # Line with no separator and not a valid continuation is ignored
                pass

    # Ensure DEFAULT section is initialized if it was the implicit start
    # though the logic above handles it via result[current_section_name]
    return result
