def retry_with_deadline(fn, retry_on, total_deadline, base_delay, clock, sleep, rand):
    start = clock()
    n = 0
    while True:
        try:
            return fn()
        except retry_on:
            n += 1
            delay = base_delay * (2 ** (n - 1)) * rand()
            if clock() + delay >= start + total_deadline:
                raise
            sleep(delay)
