def search_last_rotated(nums, target):
    n = len(nums)
    if n == 0:
        return -1

    # Modified binary search to find the last occurrence in a rotated sorted array with duplicates
    left, right = 0, n - 1

    def is_sorted(left, right):
        # Check if the subarray nums[left:right+1] is sorted (non-decreasing)
        # In a rotated sorted array, if nums[left] <= nums[right], the subarray is sorted
        # But with duplicates, this check may not be reliable, so we use a different approach
        pass

    # We'll use a different approach: find the rotation point, then search in the appropriate half
    # But with duplicates, it's tricky. Let's use a linear-ish binary search that handles duplicates.

    # Actually, let's use a recursive/iterative approach that works with duplicates:
    # At each step, we check if the mid portion is sorted. If so, search normally.
    # If not, we need to determine which half contains the target.

    # Simpler approach: since we need the LAST occurrence, we can use a modified binary search
    # that handles the rotation and duplicates.

    def binary_search_last(left, right, is_rotated):
        """
        Search for the last occurrence of target in nums[left:right+1].
        If is_rotated is True, the subarray is rotated; otherwise, it's sorted.
        """
        while left <= right:
            mid = (left + right) // 2

            if nums[mid] == target:
                # Check if there's a later occurrence
                if mid < right and nums[mid + 1] == target:
                    left = mid + 1
                else:
                    # Check if mid is in a rotated portion where a later occurrence might exist
                    # Actually, if the array is sorted in this range, this is fine.
                    # But if it's rotated, we need to be more careful.
                    return mid
            elif is_rotated:
                # Determine which half to search
                # If the left part is sorted, check if target is in it
                if nums[left] <= nums[mid]:
                    if nums[left] <= target < nums[mid]:
                        right = mid - 1
                    elif nums[mid] < target or (target >= nums[mid] and target >= nums[left]):
                        # Target might be in the right part, or we have duplicates
                        # If target >= nums[mid], it could be in the right part
                        # But we need to handle duplicates carefully
                        left = mid + 1
                    else:
                        left = mid + 1
                else:
                    # Right part is sorted
                    if nums[mid] < target <= nums[right]:
                        left = mid + 1
                    elif target <= nums[mid] and target <= nums[right]:
                        right = mid - 1
                    else:
                        right = mid - 1
            else:
                # Sorted subarray
                if nums[mid] < target:
                    left = mid + 1
                else:
                    right = mid - 1

        return -1

    # This approach is getting complicated. Let me use a simpler method:
    # Find the minimum element's index (rotation point), then split into two sorted arrays
    # and search for the last occurrence in each.

    # Find the rotation point (index of minimum element)
    def find_rotation_point():
        lo, hi = 0, n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if nums[mid] > nums[hi]:
                lo = mid + 1
            elif nums[mid] < nums[hi]:
                hi = mid
            else:
                hi -= 1
        return lo

    rot_point = find_rotation_point()

    # Now we have two sorted arrays:
    # nums[rot_point : n] and nums[0 : rot_point]

    def search_last_in_sorted(arr, start, end, target):
        """Find last occurrence of target in nums[start:end] (both inclusive), assuming sorted."""
        left, right = start, end
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                left = mid + 1  # Look for later occurrence
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    # Search in the first part: nums[0:rot_point] (sorted)
    # Search in the second part: nums[rot_point:n] (sorted)

    # But we want the LAST occurrence in the original array, which means:
    # The last occurrence in the second part (rot_point to n-1) has higher indices
    # than anything in the first part (0 to rot_point-1).
    # So search second part first, if found, return it. Else search first part.

    if rot_point < n:
        res = search_last_in_sorted(None, rot_point, n - 1, target)
        if res != -1:
            return res

    if rot_point > 0:
        res = search_last_in_sorted(None, 0, rot_point - 1, target)
        if res != -1:
            return res

    return -1
