def run(program, max_steps):
    regs = [0] * 4
    flag = 0
    pc = 0
    steps = 0

    reg_map = {"r0": 0, "r1": 1, "r2": 2, "r3": 3}
    MOD = 2**64

    def get_val(op):
        if isinstance(op, str) and op.startswith("#"):
            return int(op[1:])
        if isinstance(op, str) and op in reg_map:
            return regs[reg_map[op]]
        return 0

    while True:
        # Check bounds before fetch
        if pc < 0 or pc >= len(program):
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "fell_off"}

        # Check step limit before fetch
        if steps >= max_steps:
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "step_limit"}

        instr = program[pc]
        opcode = instr[0]

        # Execute instruction
        if opcode == "SET":
            dst = reg_map[instr[1]]
            regs[dst] = get_val(instr[2]) % MOD
            pc += 1
        elif opcode == "ADD":
            dst = reg_map[instr[1]]
            regs[dst] = (regs[dst] + get_val(instr[2])) % MOD
            pc += 1
        elif opcode == "SUB":
            dst = reg_map[instr[1]]
            regs[dst] = (regs[dst] - get_val(instr[2])) % MOD
            pc += 1
        elif opcode == "MUL":
            dst = reg_map[instr[1]]
            regs[dst] = (regs[dst] * get_val(instr[2])) % MOD
            pc += 1
        elif opcode == "CMP":
            val_a = get_val(instr[1])
            val_b = get_val(instr[2])
            flag = 1 if val_a < val_b else 0
            pc += 1
        elif opcode == "JMP":
            off = instr[1]
            target = pc + off
            if target < 0 or target >= len(program):
                steps += 1
                return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
            pc = target
        elif opcode == "JIF":
            off = instr[1]
            if flag == 1:
                target = pc + off
                if target < 0 or target >= len(program):
                    steps += 1
                    return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
                pc = target
            else:
                pc += 1
        elif opcode == "ROT":
            regs = [regs[1], regs[2], regs[3], regs[0]]
            pc += 1
        elif opcode == "HALT":
            steps += 1
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "halt"}

        steps += 1
