import copy

def merge(base, overlay):
    def get_info(k):
        # Returns (sigil_type, clean_key)
        # sigil_type: 0: remove (!), 1: set-if-absent (~), 2: prepend (+k), 3: append (k+), 4: plain
        if k.startswith('!'):
            return (0, k[1:])
        if k.startswith('~'):
            return (1, k[1:])
        if k.startswith('+'):
            return (2, k[1:])
        if k.endswith('+'):
            return (3, k[:-1])
        return (4, k)

    # Deep copy base to avoid mutation
    result = copy.deepcopy(base)

    # Sort keys: first by clean name, then by sigil priority
    # Priority: remove(0), set-if-absent(1), prepend(2), append(3), plain(4)
    sorted_overlay_keys = sorted(
        overlay.keys(), 
        key=lambda k: (get_info(k)[1], get_info(k)[0])
    )

    for ok in sorted_overlay_keys:
        sigil_type, key = get_info(ok)
        val = overlay[ok]

        if sigil_type == 0: # !key (Remove)
            result.pop(key, None)

        elif sigil_type == 1: # ~key (Set if absent)
            if key not in result:
                result[key] = copy.deepcopy(val)

        elif sigil_type == 2 or sigil_type == 3: # +key or key+ (Prepend/Append)
            if not isinstance(val, list):
                raise TypeError(f"Value for {ok} must be a list")

            current = result.get(key, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {key} must be a list for modification")

            # Ensure we are working on a copy of the list to avoid mutating base
            # since result was deepcopied, we can mutate in place here
            if sigil_type == 2: # Prepend
                result[key] = copy.deepcopy(val) + current
            else: # Append
                result[key] = current + copy.deepcopy(val)

        else: # Plain key
            if key in result:
                res_val = result[key]
                if isinstance(res_val, dict) and isinstance(val, dict):
                    result[key] = merge(res_val, val)
                elif not isinstance(res_val, dict) and not isinstance(val, dict):
                    result[key] = copy.deepcopy(val)
                else:
                    raise TypeError(f"Type mismatch for key {key}: one is dict, other is not")
            else:
                result[key] = copy.deepcopy(val)

    return result
