def search_last_rotated(nums, target):
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    # First, try to find if target exists and get last occurrence
    # In a rotated array with duplicates, binary search is tricky.
    # We'll use a modified binary search approach.

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            # Move to the right to find the last occurrence
            right = mid + 1
        elif nums[left] == nums[mid] == nums[right]:
            # All three are equal, we can't determine which side to go
            # Shrink the search space
            left += 1
            right -= 1
        elif nums[left] <= nums[mid]:
            # Left half is sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right half is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    # Check if target was found
    if left > 0 and left <= len(nums) and nums[left - 1] == target:
        return left - 1
    return -1
