import copy


def merge(base, overlay):
    """Merge overlay into base following the specified rules.

    Returns a new dict. Neither base nor overlay is mutated.
    """
    result = copy.deepcopy(base)
    if not overlay:
        return result

    # Group overlay keys by their base name and categorize by sigil
    # We need to apply keys in sorted order of the key name with sigil removed,
    # and for keys with the same base name, apply in order: remove, set-if-absent, prepend, append, plain set

    def classify_key(key):
        """Classify a key into (base_name, sigil_type) where sigil_type is one of:
        'remove', 'set_if_absent', 'prepend', 'append', 'plain'
        """
        if key.startswith('!'):
            return (key[1:], 'remove')
        elif key.startswith('~'):
            return (key[1:], 'set_if_absent')
        elif key.startswith('+'):
            # Check if it's prepending (only leading +)
            # If key is exactly '+key', then base_name is key[1:]
            # But we also need to check for trailing +
            if len(key) > 1 and key.endswith('+') and not key[1:-1].startswith('+'):
                # This is ambiguous: "+key+"? Let's re-read the spec.
                # "A key written key+ appends... A key written +key prepends it."
                # "`, `~` and `+` are sigils only as the first character of a key, and `+` is also a sigil as the last character."
                # So a key can have both leading and trailing +? The spec says "+ is also a sigil as the last character".
                # Let's think: if key starts with +, it's prepend. If key ends with +, it's append.
                # What if it has both? The spec doesn't explicitly say. Let's assume that if it starts with +, it's prepend, and the rest is the base name (which might end with +, but then that trailing + would be part of the key name).
                # Actually, re-reading: "A key written key+ appends its value... A key written +key prepends it."
                # So "key+" means base_name = key, sigil = append.
                # "+key" means base_name = key, sigil = prepend.
                # What about "+key+"? It starts with +, so base_name would be "key+" and sigil = prepend?
                # But it also ends with +, so could it be base_name = "+key" and sigil = append?
                # The order of checking matters. Let's say we check leading sigils first.
                # If it starts with '!', it's remove.
                # If it starts with '~', it's set_if_absent.
                # If it starts with '+', it's prepend, and the base name is key[1:] (even if key[1:] ends with '+').
                # If it doesn't start with a sigil but ends with '+', it's append, and base name is key[:-1].
                # Otherwise, it's plain.
                return (key[1:], 'prepend')
            else:
                return (key[1:], 'prepend')
        elif key.endswith('+') and len(key) > 1:
            return (key[:-1], 'append')
        else:
            return (key, 'plain')

    # Apply overlay keys in the specified order
    # Group by base_name, and within each group, order by sigil priority
    sigil_priority = {
        'remove': 0,
        'set_if_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4,
    }

    # Build a list of (base_name, sigil_type, original_key, value)
    entries = []
    for key, value in overlay.items():
        base_name, sigil_type = classify_key(key)
        entries.append((base_name, sigil_type, original_key := key, value))

    # Sort by base_name, then by sigil priority
    entries.sort(key=lambda x: (x[0], sigil_priority[x[1]]))

    # Apply each entry
    for base_name, sigil_type, original_key, value in entries:
        if sigil_type == 'remove':
            result.pop(base_name, None)
        elif sigil_type == 'set_if_absent':
            if base_name not in result:
                result[base_name] = value
        elif sigil_type == 'prepend':
            if not isinstance(value, list):
                raise TypeError(f"Value for prepend key '{original_key}' must be a list")
            if base_name in result and not isinstance(result[base_name], list):
                raise TypeError(f"Key '{base_name}' in result holds a non-list value, cannot prepend")
            existing = result.get(base_name, [])
            result[base_name] = value + existing
        elif sigil_type == 'append':
            if not isinstance(value, list):
                raise TypeError(f"Value for append key '{original_key}' must be a list")
            if base_name in result and not isinstance(result[base_name], list):
                raise TypeError(f"Key '{base_name}' in result holds a non-list value, cannot append")
            existing = result.get(base_name, [])
            result[base_name] = existing + value
        elif sigil_type == 'plain':
            if base_name in result:
                if isinstance(result[base_name], dict) and isinstance(value, dict):
                    result[base_name] = merge(result[base_name], value)
                elif isinstance(result[base_name], dict) or isinstance(value, dict):
                    raise TypeError(f"Cannot merge dict with non-dict for key '{base_name}'")
                else:
                    result[base_name] = value
            else:
                result[base_name] = value

    return result
