import copy


def merge(base, overlay):
    """
    Merge a configuration dict `base` with an overlay dict `overlay`.
    Returns a new dict; neither argument is mutated.
    """
    result = copy.deepcopy(base)
    _apply_overlay(result, overlay)
    return result


def _apply_overlay(result, overlay):
    """
    Apply overlay dict to result dict in place.
    Keys are applied in sorted order of the key name with its sigil removed,
    and for the same name, in order: remove (!), set-if-absent (~), prepend (+key), append (key+), plain set.
    """
    # Parse each key to determine its operation and target name
    # Operations: 'remove', 'set_if_absent', 'prepend', 'append', 'plain'
    # For 'plain', we need the original key to get the value
    # For others, the value is taken from the overlay under the sigiled key

    entries = []
    for key in overlay:
        op, name, raw_key = _parse_key(key)
        entries.append((op, name, raw_key))

    # Sort by: (name, op_order)
    # op_order: remove=0, set_if_absent=1, prepend=2, append=3, plain=4
    op_order = {'remove': 0, 'set_if_absent': 1, 'prepend': 2, 'append': 3, 'plain': 4}
    entries.sort(key=lambda e: (e[1], op_order[e[0]]))

    for op, name, raw_key in entries:
        value = overlay[raw_key]

        if op == 'remove':
            # !key: remove key from result
            result.pop(name, None)

        elif op == 'set_if_absent':
            # ~key: set key to value only if key not in result
            if name not in result:
                result[name] = copy.deepcopy(value)

        elif op == 'prepend':
            # +key: prepend value (list) to list under key
            if not isinstance(value, list):
                raise TypeError(f"Overlay value for '+{name}' must be a list")
            if name in result:
                if not isinstance(result[name], list):
                    raise TypeError(f"Result value for '{name}' is not a list")
                result[name] = value + result[name]
            else:
                result[name] = copy.deepcopy(value)

        elif op == 'append':
            # key+: append value (list) to list under key
            if not isinstance(value, list):
                raise TypeError(f"Overlay value for '{name}+' must be a list")
            if name in result:
                if not isinstance(result[name], list):
                    raise TypeError(f"Result value for '{name}' is not a list")
                result[name] = result[name] + value
            else:
                result[name] = copy.deepcopy(value)

        else:  # op == 'plain'
            # Plain key: merge recursively if both dicts, otherwise replace
            if name in result:
                existing = result[name]
                if isinstance(existing, dict) and isinstance(value, dict):
                    # Merge recursively
                    new_dict = copy.deepcopy(existing)
                    _apply_overlay(new_dict, value)
                    result[name] = new_dict
                elif isinstance(existing, dict) or isinstance(value, dict):
                    # Exactly one is a dict
                    raise TypeError(
                        f"Cannot merge: key '{name}' has a dict in one and non-dict in the other"
                    )
                else:
                    result[name] = copy.deepcopy(value)
            else:
                result[name] = copy.deepcopy(value)


def _parse_key(key):
    """
    Parse a key to determine its operation, target name, and original key.
    Sigils:
    - '!' as first character: remove, name = key[1:]
    - '~' as first character: set_if_absent, name = key[1:]
    - '+' as first character: prepend, name = key[1:]
    - '+' as last character (and not first): append, name = key[:-1]
    - Otherwise: plain, name = key

    Returns (op, name, raw_key)
    """
    if key.startswith('!'):
        return ('remove', key[1:], key)
    elif key.startswith('~'):
        return ('set_if_absent', key[1:], key)
    elif key.startswith('+'):
        return ('prepend', key[1:], key)
    elif key.endswith('+') and len(key) > 1:
        # Must not also start with '+' (already handled above)
        return ('append', key[:-1], key)
    else:
        return ('plain', key, key)
