def run(program, max_steps):
    """Execute a Kestrel-2 program and return the final state."""
    MOD = 2 ** 64
    regs = [0, 0, 0, 0]
    flag = 0
    pc = 0
    steps = 0
    reason = None
    n = len(program)

    while reason is None:
        # Check if PC is out of range before fetching
        if pc < 0 or pc >= n:
            reason = "fell_off"
            break

        # Check step limit
        if steps >= max_steps:
            reason = "step_limit"
            break

        # Fetch instruction
        instr = program[pc]
        opcode = instr[0]

        # Execute the instruction
        if opcode == "SET":
            dst = instr[1]
            src = instr[2]
            if src.startswith("r"):
                src_val = regs[int(src[1])]
            else:
                src_val = int(src[1:])  # immediate #N
            dst_idx = int(dst[1])
            regs[dst_idx] = src_val % MOD
        elif opcode == "ADD":
            dst = instr[1]
            src = instr[2]
            if src.startswith("r"):
                src_val = regs[int(src[1])]
            else:
                src_val = int(src[1:])
            dst_idx = int(dst[1])
            regs[dst_idx] = (regs[dst_idx] + src_val) % MOD
        elif opcode == "SUB":
            dst = instr[1]
            src = instr[2]
            if src.startswith("r"):
                src_val = regs[int(src[1])]
            else:
                src_val = int(src[1:])
            dst_idx = int(dst[1])
            regs[dst_idx] = (regs[dst_idx] - src_val) % MOD
        elif opcode == "MUL":
            dst = instr[1]
            src = instr[2]
            if src.startswith("r"):
                src_val = regs[int(src[1])]
            else:
                src_val = int(src[1:])
            dst_idx = int(dst[1])
            regs[dst_idx] = (regs[dst_idx] * src_val) % MOD
        elif opcode == "CMP":
            a = instr[1]
            b = instr[2]
            if a.startswith("r"):
                a_val = regs[int(a[1])]
            else:
                a_val = int(a[1:])
            if b.startswith("r"):
                b_val = regs[int(b[1])]
            else:
                b_val = int(b[1:])
            flag = 1 if a_val < b_val else 0
        elif opcode == "JMP":
            off = instr[1]
            target = pc + off
            if target < 0 or target >= n:
                reason = "bad_jump"
                break
            pc = target
        elif opcode == "JIF":
            off = instr[1]
            if flag == 1:
                target = pc + off
                if target < 0 or target >= n:
                    reason = "bad_jump"
                    break
                pc = target
        elif opcode == "ROT":
            regs = [regs[1], regs[2], regs[3], regs[0]]
        elif opcode == "HALT":
            reason = "halt"
            break
        else:
            # Should not happen for well-formed programs
            raise ValueError(f"Unknown opcode: {opcode}")

        # If we didn't break or jump, advance PC
        if reason is None and opcode not in ("JMP", "JIF"):
            pc += 1
        elif reason is None and opcode == "JIF" and flag != 1:
            # JIF that didn't jump
            pc += 1
        elif reason is None and opcode == "JMP":
            # Already set pc
            pass
        elif reason is None and opcode == "JIF" and flag == 1:
            # Already set pc
            pass

        steps += 1

    return {
        "regs": regs,
        "flag": flag,
        "pc": pc,
        "steps": steps,
        "reason": reason
    }
