def search_last_rotated(nums, target):
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    # Find the last occurrence using binary search
    # Since the array is rotated sorted, we can't directly use standard binary search
    # for the last occurrence in the usual way. We need a different approach.

    # Approach: Find the rotation point, then search in the appropriate subarray,
    # or use a modified binary search that handles rotations and duplicates.

    # Let's find the last occurrence by modifying binary search to always go right when equal.
    # But in rotated array with duplicates, it's tricky.

    # Better approach: First find the minimum element (rotation point), then do binary search
    # in the sorted subarray where target would be.

    def find_min_index(left, right):
        # Find the index of the minimum element
        while left < right:
            mid = left + (right - left) // 2
            if nums[mid] > nums[right]:
                left = mid + 1
            elif nums[mid] < nums[right]:
                right = mid
            else:
                right -= 1  # Handle duplicates at the end
        return left

    min_idx = find_min_index(left, right)

    # Now the array is split into two sorted parts:
    # [min_idx, end] and [0, min_idx - 1]

    def binary_search_last(low, high):
        # Find last occurrence of target in sorted subarray nums[low:high+1]
        result = -1
        while low <= high:
            mid = low + (high - low) // 2
            if nums[mid] == target:
                result = mid
                low = mid + 1  # Go right to find last occurrence
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return result

    # Search in the first sorted part: [0, min_idx - 1]
    if min_idx > 0:
        idx1 = binary_search_last(0, min_idx - 1)
    else:
        idx1 = -1

    # Search in the second sorted part: [min_idx, len(nums) - 1]
    idx2 = binary_search_last(min_idx, len(nums) - 1)

    # Return the larger index (last occurrence)
    if idx1 == -1:
        return idx2
    if idx2 == -1:
        return idx1
    return max(idx1, idx2)
