    last_key = None
    last_indent = 0

    for line in text.splitlines():
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            continue

        # Check for section header
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            current_section = stripped_line[1:-1].strip()
            if current_section not in result:
                result[current_section] = {}
            last_key = None
            last_indent = 0
            continue

        # Check for continuation
        # A line is a continuation if it's more indented than the previous key line
        # AND it contains no separator (= or :)
        indent = len(line) - len(line.lstrip())
        has_separator = '=' in line or ':' in line

        if last_key is not None and indent > last_indent and not has_separator:
            if current_section not in result:
                result[current_section] = {}
            result[current_section][last_key] += " " + stripped_line
            continue

        # Handle key-value pair
        sep_idx_eq = line.find('=')
        sep_idx_col = line.find(':')

        if sep_idx_eq == -1 and sep_idx_col == -1:
            # Line with no separator and not a continuation/header is ignored or handled as value?
            # Based on rules, it must be a continuation or a valid key-value. 
            # If it doesn't meet continuation criteria and has no separator, we skip.
            continue

        # Determine which separator comes first
        if sep_idx_eq == -1:
            sep_idx = sep_idx_col
        elif sep_idx_col == -1:
            sep_idx = sep_idx_eq
        else:
            sep_idx = min(sep_idx_eq, sep_idx_col)

        key = line[:sep_idx].strip().lower()
        value = line[sep_idx + 1:].strip()

        if current_section not in result:
            result[current_section] = {}

        result[current_section][key] = value
        last_key = key
        last_indent = indent

    return result
