import copy

def merge(base, overlay):
    # Create a deep copy of base to ensure no mutation
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Parsing logic to categorize keys and identify the base key name
    parsed_ops = []
    for k, v in overlay.items():
        if k.startswith('!'):
            parsed_ops.append((k[1:], 0, 'remove', v))
        elif k.startswith('~'):
            parsed_ops.append((k[1:], 1, 'set_if_absent', v))
        elif k.startswith('+'):
            parsed_ops.append((k[1:], 2, 'prepend', v))
        elif k.endswith('+'):
            parsed_ops.append((k[:-1], 3, 'append', v))
        else:
            parsed_ops.append((k, 4, 'plain', v))

    # Sort by base key name, then by the priority defined by the rule order
    parsed_ops.sort(key=lambda x: (x[0], x[1]))

    for key, _, op, val in parsed_ops:
        if op == 'remove':
            if key in result:
                del result[key]

        elif op == 'set_if_absent':
            if key not in result:
                result[key] = copy.deepcopy(val)

        elif op == 'prepend':
            if not isinstance(val, list):
                raise TypeError(f"Value for +{key} must be a list")
            current = result.get(key, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {key} must be a list to prepend")
            result[key] = copy.deepcopy(val) + copy.deepcopy(current)

        elif op == 'append':
            if not isinstance(val, list):
                raise TypeError(f"Value for {key}+ must be a list")
            current = result.get(key, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {key} must be a list to append")
            result[key] = copy.deepcopy(current) + copy.deepcopy(val)

        elif op == 'plain':
            if key in result:
                res_val = result[key]
                if isinstance(res_val, dict) and isinstance(val, dict):
                    result[key] = merge(res_val, val)
                elif isinstance(res_val, dict) or isinstance(val, dict):
                    raise TypeError(f"Conflict at {key}: exactly one of the values is a dict")
                else:
                    result[key] = copy.deepcopy(val)
            else:
                result[key] = copy.deepcopy(val)

    return result
