import copy

def merge(base, overlay):
    # Start with a deep copy of base to ensure no mutation
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Parse overlay keys into (original_key, clean_key, priority, value)
    # Priority: ! (0), ~ (1), +prefix (2), +suffix (3), plain (4)
    parsed_keys = []
    for k, v in overlay.items():
        if k.startswith('!'):
            parsed_keys.append((k, k[1:], 0, v))
        elif k.startswith('~'):
            parsed_keys.append((k, k[1:], 1, v))
        elif k.startswith('+'):
            parsed_keys.append((k, k[1:], 2, v))
        elif k.endswith('+'):
            parsed_keys.append((k, k[:-1], 3, v))
        else:
            parsed_keys.append((k, k, 4, v))

    # Sort by clean_key alphabetically, then by priority
    parsed_keys.sort(key=lambda x: (x[1], x[2]))

    for original_key, clean_key, priority, value in parsed_keys:
        if priority == 0:  # !key (remove)
            result.pop(clean_key, None)

        elif priority == 1:  # ~key (set if absent)
            if clean_key not in result:
                result[clean_key] = copy.deepcopy(value)

        elif priority == 2:  # +key (prepend)
            if not isinstance(value, list):
                raise TypeError(f"Value for {original_key} must be a list")
            current = result.get(clean_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {clean_key} must be a list to prepend")
            result[clean_key] = copy.deepcopy(value) + copy.deepcopy(current)

        elif priority == 3:  # key+ (append)
            if not isinstance(value, list):
                raise TypeError(f"Value for {original_key} must be a list")
            current = result.get(clean_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {clean_key} must be a list to append")
            result[clean_key] = copy.deepcopy(current) + copy.deepcopy(value)

        else:  # plain key
            if clean_key in result:
                val_base = result[clean_key]
                # Raise TypeError if exactly one is a dict
                if (isinstance(val_base, dict) and not isinstance(value, dict)) or \
                   (not isinstance(val_base, dict) and isinstance(value, dict)):
                    raise TypeError(f"Type mismatch for key {clean_key}: exactly one value is a dict")

                if isinstance(val_base, dict) and isinstance(value, dict):
                    result[clean_key] = merge(val_base, value)
                else:
                    result[clean_key] = copy.deepcopy(value)
            else:
                result[clean_key] = copy.deepcopy(value)

    return result
