import copy

def merge(base, overlay):
    # Work on a deep copy to ensure base is not mutated
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Parse the overlay keys to determine their operation and the target key name
    # Order of operations for the same target key: !, ~, +prefix, +suffix, plain
    op_priority = {'!': 0, '~': 1, 'pre': 2, 'app': 3, 'plain': 4}

    parsed_keys = []
    for k, v in overlay.items():
        if k.startswith('!'):
            parsed_keys.append((k[1:], op_priority['!'], v))
        elif k.startswith('~'):
            parsed_keys.append((k[1:], op_priority['~'], v))
        elif k.startswith('+'):
            parsed_keys.append((k[1:], op_priority['pre'], v))
        elif k.endswith('+'):
            parsed_keys.append((k[:-1], op_priority['app'], v))
        else:
            parsed_keys.append((k, op_priority['plain'], v))

    # Sort by target key name, then by operation priority
    parsed_keys.sort(key=lambda x: (x[0], x[1]))

    for target_key, priority, value in parsed_keys:
        if priority == op_priority['!']:
            # Remove key
            result.pop(target_key, None)

        elif priority == op_priority['~']:
            # Set if absent
            if target_key not in result:
                result[target_key] = copy.deepcopy(value)

        elif priority == op_priority['pre']:
            # Prepend to list
            if not isinstance(value, list):
                raise TypeError(f"Value for {target_key} must be a list for prepend")
            current = result.get(target_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {target_key} must be a list for prepend")
            result[target_key] = copy.deepcopy(current)
            result[target_key] = copy.deepcopy(value) + result[target_key]

        elif priority == op_priority['app']:
            # Append to list
            if not isinstance(value, list):
                raise TypeError(f"Value for {target_key} must be a list for append")
            current = result.get(target_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {target_key} must be a list for append")
            result[target_key] = copy.deepcopy(current)
            result[target_key].extend(copy.deepcopy(value))

        else:
            # Plain set / Recursive merge
            if target_key in result:
                res_val = result[target_key]
                if isinstance(res_val, dict) and isinstance(value, dict):
                    result[target_key] = merge(res_val, value)
                elif isinstance(res_val, dict) or isinstance(value, dict):
                    raise TypeError(f"Type mismatch for key {target_key}: exactly one is a dict")
                else:
                    result[target_key] = copy.deepcopy(value)
            else:
                result[target_key] = copy.deepcopy(value)

    return result
