import copy

def merge(base, overlay):
    def get_details(k):
        # Order of application for the same base key: 
        # ! (remove), ~ (set-if-absent), +k (prepend), k+ (append), k (plain)
        if k.startswith('!'):
            return k[1:], 0
        if k.startswith('~'):
            return k[1:], 1
        if k.startswith('+'):
            return k[1:], 2
        if k.endswith('+'):
            return k[:-1], 3
        return k, 4

    # Create a deep copy of base to ensure no mutation
    result = copy.deepcopy(base)

    # Sort overlay keys by the base name, then by the operation priority
    sorted_keys = sorted(overlay.keys(), key=lambda x: (get_details(x)[0], get_details(x)[1]))

    for k in sorted_keys:
        base_key, op = get_details(k)
        val = overlay[k]

        if op == 0:  # !key: remove
            result.pop(base_key, None)

        elif op == 1:  # ~key: set if absent
            if base_key not in result:
                result[base_key] = copy.deepcopy(val)

        elif op == 2:  # +key: prepend
            if not isinstance(val, list):
                raise TypeError(f"Value for {k} must be a list")
            current = result.get(base_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {base_key} must be a list for prepending")
            result[base_key] = copy.deepcopy(current)
            result[base_key] = copy.deepcopy(val) + result[base_key]

        elif op == 3:  # key+: append
            if not isinstance(val, list):
                raise TypeError(f"Value for {k} must be a list")
            current = result.get(base_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {base_key} must be a list for appending")
            result[base_key] = copy.deepcopy(current)
            result[base_key].extend(copy.deepcopy(val))

        else:  # plain key
            if base_key in result:
                old_val = result[base_key]
                if isinstance(old_val, dict) and isinstance(val, dict):
                    result[base_key] = merge(old_val, val)
                elif not isinstance(old_val, dict) and not isinstance(val, dict):
                    result[base_key] = copy.deepcopy(val)
                else:
                    raise TypeError(f"Type mismatch for key {base_key}: exactly one value is a dict")
            else:
                result[base_key] = copy.deepcopy(val)

    return result
