import copy

def merge(base, overlay):
    result = copy.deepcopy(base)

    # Group keys by their base name to handle ordering
    # Order of priority: !, ~, +prefix, +suffix, plain
    # We store them as (priority, original_key, value)
    priority_map = {'!': 0, '~': 1, 'pre': 2, 'suf': 3, 'plain': 4}

    groups = {}
    for k, v in overlay.items():
        if k.startswith('!'):
            base_name = k[1:]
            op = '!'
        elif k.startswith('~'):
            base_name = k[1:]
            op = '~'
        elif k.startswith('+'):
            base_name = k[1:]
            op = 'pre'
        elif k.endswith('+'):
            base_name = k[:-1]
            op = 'suf'
        else:
            base_name = k
            op = 'plain'

        if base_name not in groups:
            groups[base_name] = []
        groups[base_name].append((priority_map[op], k, v))

    # Sort base names alphabetically
    for base_name in sorted(groups.keys()):
        # Sort operations for the same base name by priority
        for priority, k, v in sorted(groups[base_name]):
            if k.startswith('!'):
                # Rule: !key removes key
                result.pop(base_name, None)
            elif k.startswith('~'):
                # Rule: ~key sets key only if absent
                if base_name not in result:
                    result[base_name] = copy.deepcopy(v)
            elif k.startswith('+'):
                # Rule: +key prepends list
                if not isinstance(v, list):
                    raise TypeError(f"Value for {k} must be a list")
                current = result.get(base_name, [])
                if not isinstance(current, list):
                    raise TypeError(f"Existing value for {base_name} must be a list to prepend")
                result[base_name] = copy.deepcopy(current)
                result[base_name] = copy.deepcopy(v) + result[base_name]
            elif k.endswith('+'):
                # Rule: key+ appends list
                if not isinstance(v, list):
                    raise TypeError(f"Value for {k} must be a list")
                current = result.get(base_name, [])
                if not isinstance(current, list):
                    raise TypeError(f"Existing value for {base_name} must be a list to append")
                result[base_name] = copy.deepcopy(current)
                result[base_name].extend(copy.deepcopy(v))
            else:
                # Rule: Plain key
                if base_name in result:
                    res_val = result[base_name]
                    if (isinstance(res_val, dict) and not isinstance(v, dict)) or \
                       (not isinstance(res_val, dict) and isinstance(v, dict)):
                        raise TypeError(f"Type mismatch for key {k}: one is dict, one is not")

                    if isinstance(res_val, dict) and isinstance(v, dict):
                        result[base_name] = merge(res_val, v)
                    else:
                        result[base_name] = copy.deepcopy(v)
                else:
                    result[base_name] = copy.deepcopy(v)

    return result
