import copy

def merge(base, overlay):
    # Deep copy base to avoid mutation
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Define sigil priority for keys that reduce to the same base name
    # Order: remove (!), set-if-absent (~), prepend (+key), append (key+), plain set
    PRIORITY = {
        'remove': 0,
        'set_if_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4
    }

    def parse_key(k):
        if k.startswith('!'):
            return k[1:], 'remove'
        if k.startswith('~'):
            return k[1:], 'set_if_absent'
        if k.startswith('+'):
            return k[1:], 'prepend'
        if k.endswith('+'):
            return k[:-1], 'append'
        return k, 'plain'

    # Sort keys by base name, then by the defined priority
    sorted_overlay_keys = sorted(
        overlay.keys(),
        key=lambda k: (parse_key(k)[0], PRIORITY[parse_key(k)[1]])
    )

    for k in sorted_overlay_keys:
        base_key, op = parse_key(k)
        val = overlay[k]

        if op == 'remove':
            result.pop(base_key, None)

        elif op == 'set_if_absent':
            if base_key not in result:
                result[base_key] = copy.deepcopy(val)

        elif op == 'prepend':
            if not isinstance(val, list):
                raise TypeError(f"Value for {k} must be a list")
            current = result.get(base_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {base_key} must be a list for prepending")
            result[base_key] = copy.deepcopy(current)
            result[base_key] = copy.deepcopy(val) + result[base_key]

        elif op == 'append':
            if not isinstance(val, list):
                raise TypeError(f"Value for {k} must be a list")
            current = result.get(base_key, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {base_key} must be a list for appending")
            result[base_key] = copy.deepcopy(current)
            result[base_key].extend(copy.deepcopy(val))

        elif op == 'plain':
            if base_key in result:
                res_val = result[base_key]
                if isinstance(res_val, dict) and isinstance(val, dict):
                    result[base_key] = merge(res_val, val)
                elif isinstance(res_val, dict) or isinstance(val, dict):
                    raise TypeError(f"Conflict at {base_key}: one value is a dict and the other is not")
                else:
                    result[base_key] = copy.deepcopy(val)
            else:
                result[base_key] = copy.deepcopy(val)

    return result
