    last_key = None
    last_indent = 0

    for line in text.splitlines():
        stripped_line = line.strip()

        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            continue

        # Check for section header
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            current_section = stripped_line[1:-1].strip()
            if current_section not in result:
                result[current_section] = {}
            last_key = None
            last_indent = 0
            continue

        # Determine indentation of the current line
        indent = len(line) - len(line.lstrip())

        # Find the first occurrence of = or :
        sep_idx = -1
        for char in ('=', ':'):
            idx = line.find(char)
            if idx != -1 and (sep_idx == -1 or idx < sep_idx):
                sep_idx = idx

        if sep_idx != -1:
            # Standard key-value pair
            key = line[:sep_idx].strip().lower()
            value = line[sep_idx + 1:].strip()

            if current_section not in result:
                result[current_section] = {}

            result[current_section][key] = value
            last_key = key
            last_indent = indent
        else:
            # Check if it's a continuation line
            if last_key is not None and indent > last_indent:
                if current_section not in result:
                    result[current_section] = {}

                current_val = result[current_section].get(last_key, "")
                result[current_section][last_key] = f"{current_val} {stripped_line}"
            else:
                # Line is not a header, not a KV pair, and not a valid continuation
                # Based on rules, we ignore lines that don't fit the criteria
                last_key = None
                last_indent = 0

    # Ensure DEFAULT exists if it was implicitly used
    if "DEFAULT" not in result and not result:
        # Only if the entire file was empty/comments, the prompt implies sections are dicts
        pass

    # Handle the case where keys existed before any section header
    # (Logic above already puts them in result["DEFAULT"])

    return result
