def parse(s):
    if not isinstance(s, str):
        raise ValueError("input must be a string")
    if any(c in s for c in ' \t\n\r'):
        raise ValueError("whitespace not allowed")
    if s == '':
        raise ValueError("empty string")

    # Check for leading minus
    negative = False
    rest = s
    if s.startswith('-'):
        negative = True
        rest = s[1:]
        if rest == '':
            raise ValueError("empty after minus")
    elif '-' in s:
        raise ValueError("minus not allowed except as leading sign")

    if rest == '':
        raise ValueError("empty after minus")

    # If no unit at all, it's seconds
    if rest.isdigit():
        total_ms = int(rest) * 1000
        return -total_ms if negative else total_ms

    # Parse terms
    # We need to split into terms: number+unit
    # Units: w, d, h, m, s, ms
    # Note: 'm' is minute, 'ms' is milliseconds.

    units = [('w', 604800000), ('d', 86400000), ('h', 3600000), ('m', 60000), ('s', 1000), ('ms', 1)]
    unit_map = {}
    for u, val in units:
        unit_map[u] = val

    # Strictly descending order of size
    # Sizes: w=604800000, d=86400000, h=3600000, m=60000, s=1000, ms=1
    size_order = [604800000, 86400000, 3600000, 60000, 1000, 1]
    unit_by_size = {604800000: 'w', 86400000: 'd', 3600000: 'h', 60000: 'm', 1000: 's', 1: 'ms'}

    terms = []
    i = 0
    n = len(rest)
    while i < n:
        # Parse number
        num_str = ''
        while i < n and (rest[i].isdigit() or rest[i] == '.'):
            num_str += rest[i]
            i += 1

        if num_str == '':
            raise ValueError("expected number")

        # Validate number format
        if num_str.count('.') > 1:
            raise ValueError("invalid number format")
        if '.' in num_str:
            parts = num_str.split('.')
            if len(parts) != 2 or parts[0] == '' or parts[1] == '':
                raise ValueError("invalid number format")

        # Parse unit
        if i >= n:
            raise ValueError("expected unit")

        # Try to match 'ms' first since it starts with 'm'
        unit = None
        if rest[i] == 'm':
            if i + 1 < n and rest[i+1] == 's':
                unit = 'ms'
            else:
                unit = 'm'
        elif rest[i] == 'w':
            unit = 'w'
        elif rest[i] == 'd':
            unit = 'd'
        elif rest[i] == 'h':
            unit = 'h'
        elif rest[i] == 's':
            unit = 's'
        else:
            raise ValueError("invalid unit")

        # Check that we've consumed the entire unit token
        # For 'm' we need to make sure the next char is not 's' (otherwise it should have been 'ms')
        # Wait, we already handled that above.
        # But we need to make sure there's no extra char after the unit that's part of the unit name.
        # The unit is exactly 'w', 'd', 'h', 'm', 's', or 'ms'.
        # So after determining the unit, advance i by len(unit)

        i += len(unit)

        # Check if there's more string
        # The next char, if any, must be the start of a new number (a digit)
        # Actually, terms are runs of number+unit with nothing between them.
        # So after a unit, the next char must be a digit (start of next term) or end of string.
        # Let's validate: if i < n, rest[i] must be a digit

        terms.append((num_str, unit, unit_map[unit]))

    if not terms:
        raise ValueError("no terms found")

    # Validate strictly descending order of size
    prev_size = None
    for num_str, unit, size in terms:
        if prev_size is not None and size >= prev_size:
            raise ValueError("units must be in strictly descending order")
        prev_size = size

    # Check no unit appears twice - this is implicitly checked by the strict descending order since
    # each unit has a unique size. But let's be explicit.
    seen_units = set()
    for num_str, unit, size in terms:
        if unit in seen_units:
            raise ValueError("duplicate unit")
        seen_units.add(unit)

    # Only the smallest unit present may carry a fractional part
    has_fraction = [False] * len(terms)
    for idx, (num_str, unit, size) in enumerate(terms):
        if '.' in num_str:
            has_fraction[idx] = True

    if any(has_fraction):
        # The smallest unit present must be the last term
        last_idx = len(terms) - 1
        for idx in range(len(terms)):
            if has_fraction[idx] and idx != last_idx:
                raise ValueError("only smallest unit can have fractional part")

    # Calculate total milliseconds
    # Use float for calculation then truncate toward zero
    total = 0.0
    for num_str, unit, size in terms:
        val = float(num_str) * size
        total += val

    # Truncate toward zero
    import math
    total_ms = int(math.trunc(total))

    if negative:
        total_ms = -total_ms

    return total_ms


def render(ms):
    if not isinstance(ms, int):
        # Convert if needed, but spec says integer
        ms = int(ms)

    if ms == 0:
        return '0s'

    negative = ms < 0
    total = abs(ms)

    # Units in descending order
    units = [('w', 604800000), ('d', 86400000), ('h', 3600000), ('m', 60000), ('s', 1000), ('ms', 1)]

    parts = []
    for unit, val in units:
        if total >= val:
            count = total // val
            total -= count * val
            if count > 0:
                parts.append(f"{count}{unit}")

    if not parts:
        return '0s'

    result = ''.join(parts)

    if negative:
        result = '-' + result

    return result
