def run(program, max_steps):
    regs = [0, 0, 0, 0]
    flag = 0
    pc = 0
    steps = 0
    n = len(program)

    def get_val(operand):
        if operand.startswith("r"):
            idx = int(operand[1])
            return regs[idx]
        else:  # immediate "#N"
            return int(operand[1:])

    def set_reg(operand, value):
        idx = int(operand[1])
        regs[idx] = value % (2**64)

    while True:
        # Check if pc is out of range before fetching
        if pc < 0 or pc >= n:
            return {
                "regs": regs,
                "flag": flag,
                "pc": pc,
                "steps": steps,
                "reason": "fell_off"
            }

        # Check step limit
        if steps >= max_steps:
            return {
                "regs": regs,
                "flag": flag,
                "pc": pc,
                "steps": steps,
                "reason": "step_limit"
            }

        instr = program[pc]
        opcode = instr[0]

        if opcode == "SET":
            dst, src = instr[1], instr[2]
            val = get_val(src)
            set_reg(dst, val)

        elif opcode == "ADD":
            dst, src = instr[1], instr[2]
            val = get_val(src)
            regs[int(dst[1])] = (regs[int(dst[1])] + val) % (2**64)

        elif opcode == "SUB":
            dst, src = instr[1], instr[2]
            val = get_val(src)
            regs[int(dst[1])] = (regs[int(dst[1])] - val) % (2**64)

        elif opcode == "MUL":
            dst, src = instr[1], instr[2]
            val = get_val(src)
            regs[int(dst[1])] = (regs[int(dst[1])] * val) % (2**64)

        elif opcode == "CMP":
            a, b = instr[1], instr[2]
            va = get_val(a)
            vb = get_val(b)
            flag = 1 if va < vb else 0

        elif opcode == "JMP":
            off = instr[1]
            target = pc + off
            if target < 0 or target >= n:
                return {
                    "regs": regs,
                    "flag": flag,
                    "pc": pc,
                    "steps": steps + 1,
                    "reason": "bad_jump"
                }
            pc = target

        elif opcode == "JIF":
            off = instr[1]
            if flag == 1:
                target = pc + off
                if target < 0 or target >= n:
                    return {
                        "regs": regs,
                        "flag": flag,
                        "pc": pc,
                        "steps": steps + 1,
                        "reason": "bad_jump"
                    }
                pc = target
            # if flag is 0, pc advances normally below

        elif opcode == "ROT":
            regs = [regs[1], regs[2], regs[3], regs[0]]

        elif opcode == "HALT":
            steps += 1
            return {
                "regs": regs,
                "flag": flag,
                "pc": pc,
                "steps": steps,
                "reason": "halt"
            }

        # Increment steps for all non-HALT instructions
        steps += 1

        # Advance pc for non-jump-taken instructions
        if opcode != "JMP" and not (opcode == "JIF" and flag == 1):
            pc += 1

    # Should never reach here
    return {
        "regs": regs,
        "flag": flag,
        "pc": pc,
        "steps": steps,
        "reason": "step_limit"
    }
