def search_last_rotated(nums, target):
    if not nums:
        return -1

    def binary_search_left(nums, target, left, right):
        # Binary search for the leftmost occurrence of target
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                right = mid - 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    def binary_search_right(nums, target, left, right):
        # Binary search for the rightmost occurrence of target
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    # Find the pivot (index of the smallest element)
    def find_pivot(nums):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            # Check if mid is the pivot
            if mid < right and nums[mid] > nums[mid + 1]:
                return mid + 1
            if mid > left and nums[mid] < nums[mid - 1]:
                return mid
            # Decide which half to search
            if nums[mid] >= nums[left]:
                left = mid + 1
            else:
                right = mid - 1
        return 0

    pivot = find_pivot(nums)

    # Determine which half to search
    if nums[pivot] <= target <= nums[0]:
        # Target is in the right half [pivot, end]
        # First find the rightmost occurrence
        result = binary_search_right(nums, target, pivot, len(nums) - 1)
        return result
    else:
        # Target is in the left half [0, pivot - 1]
        # First find the rightmost occurrence
        result = binary_search_right(nums, target, 0, pivot - 1)
        return result
