import copy


def merge(base, overlay):
    """Merge base and overlay dicts according to the specified rules.

    Returns a new dict combining base with overlay. Neither argument is mutated.
    """
    result = copy.deepcopy(base)
    _apply_overlay(result, overlay)
    return result


def _apply_overlay(result, overlay):
    """Apply overlay to result in-place according to the rules."""
    if not overlay:
        return

    # Parse all keys into (base_name, sigil, priority)
    # Sigils: '!' (remove), '~' (set-if-absent), '+' prefix (prepend), '+' suffix (append), None (plain)
    # Priority order for same base name: remove(0), set-if-absent(1), prepend(2), append(3), plain(4)
    parsed = []
    for key in overlay:
        base_name, sigil, priority = _parse_key(key)
        parsed.append((base_name, sigil, priority, key))

    # Sort by base_name first, then by priority
    parsed.sort(key=lambda x: (x[0], x[2]))

    # Apply each key
    for base_name, sigil, priority, original_key in parsed:
        value = overlay[original_key]

        if sigil == '!':
            # Remove key from result
            if base_name in result:
                del result[base_name]

        elif sigil == '~':
            # Set only if not present
            if base_name not in result:
                result[base_name] = value

        elif sigil == '+':
            # Append: key+
            if not isinstance(value, list):
                raise TypeError(f"Value for key '{original_key}' must be a list for append operation")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Key '{base_name}' in result must hold a list for append operation")
                result[base_name].extend(value)
            else:
                result[base_name] = list(value)

        elif sigil == '-':
            # Prepend: +key
            if not isinstance(value, list):
                raise TypeError(f"Value for key '{original_key}' must be a list for prepend operation")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Key '{base_name}' in result must hold a list for prepend operation")
                result[base_name] = value + result[base_name]
            else:
                result[base_name] = list(value)

        else:
            # Plain set or recursive merge
            if base_name in result:
                result_val = result[base_name]
                overlay_val = value
                if isinstance(result_val, dict) and isinstance(overlay_val, dict):
                    # Recursively merge
                    _apply_overlay(result_val, overlay_val)
                elif isinstance(result_val, dict) or isinstance(overlay_val, dict):
                    # Exactly one is a dict
                    raise TypeError(f"Cannot merge: one value is a dict for key '{base_name}'")
                else:
                    result[base_name] = value
            else:
                result[base_name] = value


def _parse_key(key):
    """Parse a key to extract base name, sigil, and priority.

    Returns (base_name, sigil, priority) where:
    - sigil is '!', '~', '+' (append), '-' (prepend), or None (plain)
    - priority: 0=remove, 1=set-if-absent, 2=prepend, 3=append, 4=plain
    """
    if not isinstance(key, str):
        # Non-string keys are plain
        return (key, None, 4)

    # Check for sigils
    if len(key) > 0 and key[0] == '!':
        # !key - remove
        if len(key) == 1:
            # Just "!" - this is a plain key named "!"
            return ("!", None, 4)
        return (key[1:], '!', 0)

    if len(key) > 0 and key[0] == '~':
        # ~key - set if absent
        if len(key) == 1:
            # Just "~" - this is a plain key named "~"
            return ("~", None, 4)
        return (key[1:], '~', 1)

    if len(key) > 1 and key[0] == '+':
        # +key - prepend
        # But + at the end is append, so check if it's only + at start
        if len(key) == 2 and key[1] == '+':
            # "++" - ambiguous, treat as plain? Let's say + at start means prepend, + at end means append
            # "++" has + at both start and end. Per rules: + is sigil as first char AND as last char
            # This is ambiguous. Let's treat it as a plain key "++" since both sigils present is unusual.
            # Actually, let's re-read: "A key written key+ appends" and "A key written +key prepends"
            # So "++" would be: starts with + (prepend) and ends with + (append)? That's conflicting.
            # I'll treat it as a plain key to be safe, since the rules specify distinct forms.
            return ("++", None, 4)
        # Check if last char is also +
        if key[-1] == '+':
            # Both start and end with + - ambiguous, treat as plain
            return (key, None, 4)
        return (key[1:], '-', 2)

    if len(key) > 1 and key[-1] == '+':
        # key+ - append
        return (key[:-1], '+', 3)

    # Plain key
    return (key, None, 4)
