def search_last_rotated(nums, target):
    """
    Search for the last occurrence of target in a rotated sorted array with duplicates.
    Returns the index of the last occurrence, or -1 if not found.
    """
    def binary_search_last(arr, target):
        """Binary search for the last occurrence of target in a sorted array."""
        left, right = 0, len(arr) - 1
        last_found = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                last_found = mid
                left = mid + 1
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return last_found

    def find_last(arr, target):
        """
        Recursive helper to find the last occurrence of target in rotated sorted array.
        """
