        last_result = -1

        while left <= right:
            mid = (left + right) // 2

            if arr[mid] == target:
                # We found target at mid. Now we need to check if there are
                # more occurrences to the right.
                last_result = mid
                # Try to find further occurrences to the right
                search_right = True
                # Check if the right part could contain target
                if left <= right:
                    # We need to determine which side to search
                    # If arr[left] == arr[mid] == arr[right], we can't decide
                    if arr[left] == arr[mid] and arr[mid] == arr[right]:
                        # Cannot decide, need to search both sides
                        # Search right side first to find last occurrence
                        r_left, r_right = mid + 1, right
                        l_left, l_right = left, mid - 1

                        # Search right portion
                        res = find_last_in_range(arr, target, r_left, r_right)
                        if res != -1:
                            last_result = res
                        # Also need to check left portion for earlier occurrences
                        # but we only care about last, so if right side has it, that's better
                        # But we still need to check left if right side doesn't have it
                        # Actually, since we want last, we should check right first
                        # and if nothing found there, check left
                        if res == -1:
                            res = find_last_in_range(arr, target, l_left, l_right)
                            if res != -1:
                                last_result = res

                        return last_result

                    if arr[left] <= target and target <= arr[right]:
                        # The array portion from left to right is sorted
                        # Use standard binary search for last occurrence
                        return binary_search_last_on_range(arr, target, left, right, last_result)
                    else:
                        # Need to check which side is sorted
                        if arr[left] <= arr[mid]:
                            # Left side is sorted
                            if arr[left] <= target <= arr[mid]:
                                # Target could be in left side
                                res = binary_search_last_on_range(arr, target, left, mid - 1, -1)
                                if res != -1:
                                    last_result = res
                                # Also check right side
                                res = find_last_in_range(arr, target, mid + 1, right)
                                if res != -1:
                                    last_result = res
                            else:
                                last_result = find_last_in_range(arr, target, mid + 1, right)
                        else:
                            # Right side is sorted
                            if arr[mid + 1] <= target <= arr[right]:
                                res = binary_search_last_on_range(arr, target, mid + 1, right, -1)
                                if res != -1:
                                    last_result = res
                                res = find_last_in_range(arr, target, left, mid - 1)
                                if res != -1:
                                    last_result = res
                            else:
                                last_result = find_last_in_range(arr, target, left, mid - 1)

                        return last_result
                else:
                    return last_result

            # Determine which side is sorted
            if arr[left] == arr[mid]:
                # Cannot determine, move left
                left += 1
            elif arr[left] < arr[mid]:
                # Left side is sorted
                if arr[left] <= target < arr[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # Right side is sorted
                if arr[mid + 1] <= target <= arr[right]:
                    left = mid + 1
                else:
                    right = mid - 1

        return last_result

    def binary_search_last_on_range(arr, target, lo, hi, current_last):
        """Binary search for last occurrence in range [lo, hi] which is assumed sorted."""
        if lo > hi:
            return current_last
        left, right = lo, hi
        found = current_last
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == target:
                found = mid
                left = mid + 1
            elif arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return found

    def find_last_in_range(arr, target, lo, hi):
        """Find last occurrence of target in arr[lo:hi+1]."""
        if lo > hi:
            return -1
        if lo == 0 and hi == len(arr) - 1:
            return find_last(arr, target)
        # Recursive call
        return find_last_in_range_helper(arr, target, lo, hi)

    def find_last_in_range_helper(arr, target, lo, hi):
        """Helper for find_last_in_range."""
        while lo <= hi:
            mid = (lo + hi) // 2
            if arr[mid] == target:
                found = mid
                lo = mid + 1
                # Continue searching to the right for last occurrence
                # But we need to be careful with rotation
                # Just do a simple scan from mid to hi for simplicity
                # Actually, let's just do iterative binary search for last in this subarray
                # But subarray may not be sorted, so we need to use the same logic
                return find_last_recursive(arr, target, lo - 1, hi)
            if arr[lo] == arr[mid]:
                lo += 1
            elif arr[lo] < arr[mid]:
                if arr[lo] <= target < arr[mid]:
                    hi = mid - 1
                else:
                    lo = mid + 1
            else:
                if arr[mid + 1] <= target <= arr[hi]:
                    lo = mid + 1
                else:
                    hi = mid - 1
        return -1

    def find_last_recursive(arr, target, lo, hi):
        """Recursive approach to find last occurrence."""
        if lo > hi:
            return -1
        if lo == hi:
            if arr[lo] == target:
                return lo
            return -1
        mid = (lo + hi) // 2
        if arr[mid] == target:
            # Search right for last occurrence
            res = find_last_recursive(arr, target, mid + 1, hi)
            if res != -1:
                return res
            return mid
        if arr[lo] == arr[mid]:
            # Ambiguous, search right
            res = find_last_recursive(arr, target, mid + 1, hi)
            if res != -1:
                return res
            # Also check lo
            if arr[lo] == target:
                return lo
            return -1
        if arr[lo] < arr[mid]:
            # Left half is sorted
            if arr[lo] <= target <= arr[mid]:
                res = find_last_recursive(arr, target, lo, mid - 1)
                if res != -1:
                    return res
                res = find_last_recursive(arr, target, mid + 1, hi)
                return res
            else:
                return find_last_recursive(arr, target, mid + 1, hi)
        else:
            # Right half is sorted
            if arr[mid + 1] <= target <= arr[hi]:
                res = find_last_recursive(arr, target, mid + 1, hi)
                if res != -1:
                    return res
                res = find_last_recursive(arr, target, lo, mid - 1)
                return res
            else:
                return find_last_recursive(arr, target, lo, mid - 1)

    if not nums:
        return -1

    # Simple approach: handle with recursive binary search
    return find_last_recursive(nums, target, 0, len(nums) - 1)
