import copy

def merge(base, overlay):
    def get_info(k):
        # Sigil priority: remove (!), set-if-absent (~), prepend (+start), append (+end), plain
        if k.startswith('!'):
            return k[1:], 0
        if k.startswith('~'):
            return k[1:], 1
        if k.startswith('+'):
            return k[1:], 2
        if k.endswith('+'):
            return k[:-1], 4
        return k, 3 # Use 3 for plain to allow sorting logic

    # Correcting priority to match requirements: remove, set-if-absent, prepend, append, plain set
    # !: 0, ~: 1, +key: 2, key+: 3, plain: 4
    def get_priority(k):
        if k.startswith('!'): return 0
        if k.startswith('~'): return 1
        if k.startswith('+'): return 2
        if k.endswith('+'): return 3
        return 4

    def get_clean_key(k):
        if k.startswith('!'): return k[1:]
        if k.startswith('~'): return k[1:]
        if k.startswith('+'): return k[1:]
        if k.endswith('+'): return k[:-1]
        return k

    result = copy.deepcopy(base)

    # Sort keys by clean name, then by the specified priority
    sorted_overlay_keys = sorted(
        overlay.keys(), 
        key=lambda k: (get_clean_key(k), get_priority(k))
    )

    for ok in sorted_overlay_keys:
        ov = overlay[ok]
        clean = get_clean_key(ok)
        priority = get_priority(ok)

        if priority == 0: # !key
            result.pop(clean, None)

        elif priority == 1: # ~key
            if clean not in result:
                result[clean] = copy.deepcopy(ov)

        elif priority == 2: # +key (prepend)
            if not isinstance(ov, list):
                raise TypeError(f"Value for {ok} must be a list")
            current = result.get(clean, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {clean} must be a list")
            result[clean] = copy.deepcopy(current)
            result[clean] = copy.deepcopy(ov) + result[clean]

        elif priority == 3: # key+ (append)
            if not isinstance(ov, list):
                raise TypeError(f"Value for {ok} must be a list")
            current = result.get(clean, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {clean} must be a list")
            result[clean] = copy.deepcopy(current)
            result[clean].extend(copy.deepcopy(ov))

        else: # plain key
            if clean in result:
                rv = result[clean]
                if isinstance(rv, dict) and isinstance(ov, dict):
                    result[clean] = merge(rv, ov)
                elif not isinstance(rv, dict) and not isinstance(ov, dict):
                    result[clean] = copy.deepcopy(ov)
                else:
                    raise TypeError(f"Type mismatch at {clean}: one is dict, other is not")
            else:
                result[clean] = copy.deepcopy(ov)

    return result
