def parse_ini(text):
    result = {}
    current_section = None
    last_key = None  # track last key in current section for continuation

    lines = text.splitlines()

    for line in lines:
        stripped = line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Check for comment
        if stripped[0] in (';', '#'):
            continue

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            section_name = stripped[1:-1]
            if section_name not in result:
                result[section_name] = {}
            current_section = section_name
            last_key = None
            continue

        # Default section for keys before any header
        if current_section is None:
            if 'DEFAULT' not in result:
                result['DEFAULT'] = {}
            current_section = 'DEFAULT'

        # Check if this is a continuation line:
        # More indented than the key line before it and contains no separator
        # We need to track indentation of the previous key line

        # First, check if this line has a separator (= or :)
        sep_pos = _find_separator(stripped)

        if sep_pos is not None:
            # This is a key-value pair
            key = stripped[:sep_pos].strip().lower()
            value = stripped[sep_pos + 1:].strip()

            if current_section not in result:
                result[current_section] = {}

            result[current_section][key] = value
            last_key = key
            # Store the indentation for continuation detection
            # We'll track this by storing the indent of the last key line
            result[current_section].setdefault('_last_indent', len(line) - len(line.lstrip()))
        else:
            # No separator - could be a continuation
            # Check if this line is more indented than the previous key line
            if last_key is not None and current_section in result:
                current_indent = len(line) - len(line.lstrip())
                last_indent = result[current_section].get('_last_indent', 0)

                if current_indent > last_indent:
                    # Continuation line
                    existing_value = result[current_section].get(last_key, '')
                    new_value = (existing_value + ' ' + stripped) if existing_value else stripped
                    result[current_section][last_key] = new_value
                    # Update last_indent to be the max? No, keep it the same for further continuations
                    # Actually, continuation lines should be compared to the original key line indent
                    # So we keep _last_indent as the indent of the key line
                else:
                    # Not a valid continuation, and no separator - skip or handle as error
                    # Per the spec, this might be an edge case; we'll skip it
                    pass
            else:
                # No previous key or no section, ignore
                pass

    # Clean up _last_indent from all sections
    for section in result:
        if '_last_indent' in result[section]:
            del result[section]['_last_indent']

    return result


def _find_separator(stripped):
    """Find the position of the first = or : in the string, whichever comes first."""
    eq_pos = stripped.find('=')
    colon_pos = stripped.find(':')

    candidates = [p for p in (eq_pos, colon_pos) if p != -1]
    if not candidates:
        return None
    return min(candidates)
