import copy


def _classify_key(key):
    """
    Classify a key into (sigil, base_name).
    Sigils:
      - '!' prefix: remove
      - '~' prefix: set-if-absent
      - '+' prefix: prepend
      - '+' suffix: append
      - otherwise: plain set
    """
    if key.startswith('!') and len(key) > 1:
        return ('remove', key[1:])
    if key.startswith('~') and len(key) > 1:
        return ('set_if_absent', key[1:])
    if key.startswith('+') and len(key) > 1:
        return ('prepend', key[1:])
    if key.endswith('+') and len(key) > 1:
        return ('append', key[:-1])
    return ('plain', key)


def _sigil_order(sigil):
    """
    Order for applying keys that reduce to the same base name:
    remove, set-if-absent, prepend, append, plain set.
    """
    order = {
        'remove': 0,
        'set_if_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4,
    }
    return order.get(sigil, 5)


def _apply_overlay_to_dict(result, overlay):
    """
    Apply overlay to result in-place. result is assumed to be a dict.
    """
    if not isinstance(overlay, dict):
        return

    # Group keys by their base name, keeping track of sigil and original key
    # We need to apply keys in sorted order of base name, and for same base name,
    # by sigil order: remove, set_if_absent, prepend, append, plain
    key_groups = {}  # base_name -> list of (sigil, original_key, value)

    for key, value in overlay.items():
        sigil, base_name = _classify_key(key)
        if base_name not in key_groups:
            key_groups[base_name] = []
        key_groups[base_name].append((sigil, key, value))

    # Sort by base_name, then by sigil order
    sorted_base_names = sorted(key_groups.keys())

    for base_name in sorted_base_names:
        entries = key_groups[base_name]
        # Sort entries by sigil order
        entries.sort(key=lambda x: _sigil_order(x[0]))

        for sigil, original_key, value in entries:
            if sigil == 'remove':
                result.pop(base_name, None)

            elif sigil == 'set_if_absent':
                if base_name not in result:
                    result[base_name] = copy.deepcopy(value)
                # else: do nothing

            elif sigil == 'prepend':
                # value must be a list
                if not isinstance(value, list):
                    raise TypeError(f"Value for prepend key '{original_key}' must be a list")
                # result[base_name] must be a list if present
                if base_name in result:
                    if not isinstance(result[base_name], list):
                        raise TypeError(f"Key '{base_name}' in result holds something that is not a list, cannot prepend")
                    result[base_name] = value + result[base_name]
                else:
                    result[base_name] = copy.deepcopy(value)

            elif sigil == 'append':
                # value must be a list
                if not isinstance(value, list):
                    raise TypeError(f"Value for append key '{original_key}' must be a list")
                # result[base_name] must be a list if present
                if base_name in result:
                    if not isinstance(result[base_name], list):
                        raise TypeError(f"Key '{base_name}' in result holds something that is not a list, cannot append")
                    result[base_name] = result[base_name] + value
                else:
                    result[base_name] = copy.deepcopy(value)

            elif sigil == 'plain':
                if base_name in result:
                    existing = result[base_name]
                    if isinstance(existing, dict) and isinstance(value, dict):
                        # Merge recursively
                        _apply_overlay_to_dict(existing, value)
                    elif isinstance(existing, dict) != isinstance(value, dict):
                        raise TypeError(f"Plain key '{base_name}': one value is a dict and the other is not")
                    else:
                        result[base_name] = copy.deepcopy(value)
                else:
                    result[base_name] = copy.deepcopy(value)


def merge(base, overlay):
    """
    Merge a configuration dict base with an overlay dict.
    Returns a new dict; neither argument is mutated.
    """
    # Start with a deep copy of base
    result = copy.deepcopy(base) if isinstance(base, dict) else {}

    if overlay is None or not isinstance(overlay, dict):
        return result

    _apply_overlay_to_dict(result, overlay)
    return result
