def run(program, max_steps):
    regs = [0, 0, 0, 0]
    flag = 0
    pc = 0
    steps = 0
    n = len(program)

    def resolve(src, reg_vals):
        if src.startswith('#'):
            return int(src[1:])
        else:
            r = int(src[1])
            return reg_vals[r]

    while True:
        if pc < 0 or pc >= n:
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "fell_off"}

        if steps == max_steps:
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "step_limit"}

        instr = program[pc]
        opcode = instr[0]

        if opcode == "SET":
            dst_idx = int(instr[1][1])
            src_val = resolve(instr[2], regs)
            regs[dst_idx] = src_val
            pc += 1
            steps += 1

        elif opcode == "ADD":
            dst_idx = int(instr[1][1])
            src_val = resolve(instr[2], regs)
            regs[dst_idx] = (regs[dst_idx] + src_val) % (2**64)
            pc += 1
            steps += 1

        elif opcode == "SUB":
            dst_idx = int(instr[1][1])
            src_val = resolve(instr[2], regs)
            regs[dst_idx] = (regs[dst_idx] - src_val) % (2**64)
            pc += 1
            steps += 1

        elif opcode == "MUL":
            dst_idx = int(instr[1][1])
            src_val = resolve(instr[2], regs)
            regs[dst_idx] = (regs[dst_idx] * src_val) % (2**64)
            pc += 1
            steps += 1

        elif opcode == "CMP":
            a_val = resolve(instr[1], regs)
            b_val = resolve(instr[2], regs)
            flag = 1 if a_val < b_val else 0
            pc += 1
            steps += 1

        elif opcode == "JMP":
            off = instr[1]
            target = pc + off
            steps += 1
            if target < 0 or target >= n:
                return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
            pc = target

        elif opcode == "JIF":
            off = instr[1]
            target = pc + off
            steps += 1
            if flag == 1:
                if target < 0 or target >= n:
                    return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
                pc = target
            # else: no jump, pc remains unchanged (but we don't advance)
            # Actually, "does nothing" means pc doesn't change? 
            # Wait, the rules say "Every instruction other than a jump that is taken advances the program counter to the next address."
            # So JIF that doesn't jump is "not a jump that is taken", so pc advances.
            if flag == 0:
                pc = pc + 1

        elif opcode == "ROT":
            r0, r1, r2, r3 = regs
            regs = [r1, r2, r3, r0]
            pc += 1
            steps += 1

        elif opcode == "HALT":
            steps += 1
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "halt"}

        else:
            # Should not happen for well-formed program
            pc += 1
            steps += 1
