def _apply_overlay(result, overlay):
    if not overlay:
        return

    # Parse keys to determine their operation and effective name
    parsed = []
    for key in overlay:
        sigil = None
        name = key
        is_plain = True

        # Check for leading sigils
        if key.startswith('!'):
            sigil = 'remove'
            name = key[1:]
            is_plain = False
        elif key.startswith('~'):
            sigil = 'set_if_absent'
            name = key[1:]
            is_plain = False
        elif key.startswith('+') and (len(key) <= 1 or not key.endswith('+')):
            # +key: prepend (only if it doesn't end with + to distinguish from key+)
            # Actually need to be careful: +key means prepend, key+ means append
            # If key starts with +, it's prepend. But we also need to check if it ends with + for append.
            # The spec says: "A key written key+ appends... A key written +key prepends"
            # and "+ is also a sigil as the last character"
            # So we need to handle both ends.
            pass

        # Let's re-parse more carefully
        parsed.append((key, sigil, name, is_plain))

    # Actually, let's redo the parsing properly
    parsed = []
    for key in overlay:
        effective_name = key
        operation = 'plain'

        # Check for remove sigil
        if key.startswith('!'):
            operation = 'remove'
            effective_name = key[1:]
        elif key.startswith('~'):
            operation = 'set_if_absent'
            effective_name = key[1:]
        elif key.startswith('+') and not key.endswith('+'):
            # +key: prepend
            operation = 'prepend'
            effective_name = key[1:]
        elif key.endswith('+') and not key.startswith('+'):
            # key+: append
            operation = 'append'
            effective_name = key[:-1]
        elif key.startswith('+') and key.endswith('+') and len(key) > 1:
            # Both? The spec doesn't explicitly handle this. Let's assume prepend takes precedence or treat as prepend.
            # Actually, looking at the spec: "+key" prepends, "key+" appends.
            # If a key starts and ends with +, it's ambiguous. Let's assume prepend (first char sigil takes priority).
            operation = 'prepend'
            effective_name = key[1:]
        else:
            operation = 'plain'
            effective_name = key

        parsed.append((effective_name, operation, key, overlay[key]))

    # Sort by effective name, then by operation order: remove, set_if_absent, prepend, append, plain
    op_order = {
        'remove': 0,
        'set_if_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4
    }

    parsed.sort(key=lambda x: (x[0], op_order.get(x[1], 5)))

    for effective_name, operation, original_key, value in parsed:
        if operation == 'remove':
            if effective_name in result:
                del result[effective_name]
        elif operation == 'set_if_absent':
            if effective_name not in result:
                result[effective_name] = copy.deepcopy(value)
        elif operation == 'prepend':
            if not isinstance(value, list):
                raise TypeError("Prepend value must be a list")
            if effective_name in result:
                if not isinstance(result[effective_name], list):
                    raise TypeError("Prepend target must be a list")
                result[effective_name] = copy.deepcopy(value) + result[effective_name]
            else:
                result[effective_name] = copy.deepcopy(value)
        elif operation == 'append':
            if not isinstance(value, list):
                raise TypeError("Append value must be a list")
            if effective_name in result:
                if not isinstance(result[effective_name], list):
                    raise TypeError("Append target must be a list")
                result[effective_name] = result[effective_name] + copy.deepcopy(value)
            else:
                result[effective_name] = copy.deepcopy(value)
        elif operation == 'plain':
            if effective_name in result:
                result_val = result[effective_name]
                overlay_val = value
                if isinstance(result_val, dict) and isinstance(overlay_val, dict):
                    _apply_overlay(result_val, overlay_val)
                elif isinstance(result_val, dict) or isinstance(overlay_val, dict):
                    raise TypeError("Cannot merge dict with non-dict or vice versa")
                else:
                    result[effective_name] = copy.deepcopy(value)
            else:
                result[effective_name] = copy.deepcopy(value)
