def parse_ini(text):
    result = {}
    current_section = "DEFAULT"
    last_key = None
    last_indent = 0

    lines = text.splitlines()

    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith(';') or stripped.startswith('#'):
            continue

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1]
            if current_section not in result:
                result[current_section] = {}
            last_key = None
            last_indent = 0
            continue

        # Determine indentation of the current line
        indent = len(line) - len(line.lstrip())

        # Check for key-value separators
        sep_idx_eq = line.find('=')
        sep_idx_col = line.find(':')

        # Find the first occurring separator
        if sep_idx_eq == -1:
            sep_idx = sep_idx_col
        elif sep_idx_col == -1:
            sep_idx = sep_idx_eq
        else:
            sep_idx = min(sep_idx_eq, sep_idx_col)

        if sep_idx != -1:
            # It is a key-value line
            key = line[:sep_idx].strip().lower()
            value = line[sep_idx + 1:].strip()

            if current_section not in result:
                result[current_section] = {}

            result[current_section][key] = value
            last_key = key
            last_indent = indent
        else:
            # No separator: check if it's a continuation
            if last_key is not None and indent > last_indent:
                if current_section not in result:
                    result[current_section] = {}

                current_val = result[current_section].get(last_key, "")
                result[current_section][last_key] = f"{current_val} {stripped}"
            else:
                # Line has no separator and is not a valid continuation; ignore it
                pass

    # Ensure DEFAULT exists if it was used or implied
    if "DEFAULT" not in result and not result:
        # If the input was empty or only comments, 
        # the prompt implies we return the structure.
        pass
    elif "DEFAULT" not in result and any(k == "DEFAULT" for k in result.keys()):
        pass # already handled

    # If there were keys before any section, they are in DEFAULT
    # If DEFAULT was the active section at start, it should be in result if it got keys
    # but since we only add sections when found or keys are added, 
    # we must ensure the logic covers the "DEFAULT" case explicitly.

    # The loop logic `if current_section not in result: result[current_section] = {}`
    # handles both the initial DEFAULT and subsequent sections.

    return result
