import copy

def merge(base, overlay):
    # Deep copy base to ensure no mutation
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Define sigil priority for keys reducing to the same name
    # remove (!), set-if-absent (~), prepend (+key), append (key+), plain set (key)
    PRIORITY = {
        'remove': 0,
        'set_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4
    }

    def parse_key(k):
        if k.startswith('!'):
            return k[1:], 'remove'
        if k.startswith('~'):
            return k[1:], 'set_absent'
        if k.startswith('+'):
            return k[1:], 'prepend'
        if k.endswith('+'):
            return k[:-1], 'append'
        return k, 'plain'

    # Collect and sort overlay keys
    parsed_keys = []
    for k in overlay:
        name, op = parse_key(k)
        parsed_keys.append((name, op, k))

    # Sort by: 1. Name (alphabetical), 2. Priority of operation
    parsed_keys.sort(key=lambda x: (x[0], PRIORITY[x[1]]))

    for name, op, original_key in parsed_keys:
        val = overlay[original_key]

        if op == 'remove':
            if name in result:
                del result[name]

        elif op == 'set_absent':
            if name not in result:
                result[name] = copy.deepcopy(val)

        elif op == 'prepend':
            if not isinstance(val, list):
                raise TypeError(f"Value for {original_key} must be a list")
            current = result.get(name, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {name} must be a list to prepend")
            result[name] = copy.deepcopy(current)
            result[name] = copy.deepcopy(val) + result[name]

        elif op == 'append':
            if not isinstance(val, list):
                raise TypeError(f"Value for {original_key} must be a list")
            current = result.get(name, [])
            if not isinstance(current, list):
                raise TypeError(f"Existing value for {name} must be a list to append")
            result[name] = copy.deepcopy(current)
            result[name].extend(copy.deepcopy(val))

        elif op == 'plain':
            if name in result:
                res_val = result[name]
                if isinstance(res_val, dict) and isinstance(val, dict):
                    result[name] = merge(res_val, val)
                elif isinstance(res_val, dict) or isinstance(val, dict):
                    raise TypeError(f"Type mismatch for key {name}: exactly one is a dict")
                else:
                    result[name] = copy.deepcopy(val)
            else:
                result[name] = copy.deepcopy(val)

    return result
