import copy


def merge(base, overlay):
    """
    Returns a new dict combining base with overlay per the specified rules.
    Neither base nor overlay is mutated.
    """
    if overlay is None:
        overlay = {}
    result = copy.deepcopy(base)
    _apply_overlay(result, overlay)
    return result


def _classify_key(key):
    """
    Classify a key into (sigil_type, base_key) where sigil_type is one of:
    'remove', 'set_if_absent', 'prepend', 'append', 'plain'
    and base_key is the key name with sigils removed.
    """
    if not isinstance(key, str):
        # Non-string keys are always plain
        return ('plain', key)

    if len(key) == 0:
        return ('plain', key)

    first = key[0]
    last = key[-1] if len(key) > 1 else None  # avoid confusion for single-char keys

    # Check sigils
    # !key -> remove
    if first == '!' and len(key) > 1:
        return ('remove', key[1:])

    # ~key -> set-if-absent
    if first == '~' and len(key) > 1:
        return ('set_if_absent', key[1:])

    # +key (prepend) - first char is '+' and not the only char, and last char is not '+'
    # Actually, we need to be careful: "+key" means the whole key starts with '+'
    # "key+" means the whole key ends with '+'
    # What about "+key+"? That's ambiguous. Let's think...
    # The spec says: "A key written `key+` appends... A key written `+key` prepends it."
    # And: "`!`, `~` and `+` are sigils only as the first character of a key, and `+` is also a sigil as the last character."
    # So '+' is a sigil as first char OR as last char.
    # A key like "+foo" -> prepend foo
    # A key like "foo+" -> append foo
    # A key like "+foo+" -> this starts with '+' and ends with '+'. Which wins?
    # I think we should check: if first is '+', it's prepend. If last is '+' (and first isn't a sigil that takes precedence?), it's append.
    # But what if both? Let's assume that if first char is '+', it's prepend (the whole key minus the first char is the base).
    # If first char is not a sigil but last char is '+', it's append.

    if first == '+' and len(key) > 1:
        # Could be prepend: +key
        # But what if the key is just "+"? Then len is 1, we skip.
        # What if key is "++"? First is '+', so prepend, base key is "+".
        return ('prepend', key[1:])

    if last == '+' and first != '+' and len(key) > 1:
        # This handles "key+" where key doesn't start with '+'
        # But wait, we already handled the case where first is '+'. So if we get here, first is not '+'.
        return ('append', key[:-1])

    # Plain key
    return ('plain', key)


def _key_sort_key(key):
    """
    Return a sort key for a key in the overlay.
    Sort by: base key name (with sigils removed), then by sigil priority.
    Priority order: remove (0), set-if-absent (1), prepend (2), append (3), plain set (4)
    """
    sigil_type, base_key = _classify_key(key)
    priority_map = {
        'remove': 0,
        'set_if_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4,
    }
    priority = priority_map[sigil_type]
    # For sorting, we want to sort by base_key first, then by priority
    # base_key could be non-string, so we need a consistent way to compare
    # We'll try to convert to a string for comparison purposes, but handle non-strings
    if isinstance(base_key, str):
        sort_key_str = base_key
    else:
        sort_key_str = str(base_key)
    return (sort_key_str, priority)


def _apply_overlay(result, overlay):
    """
    Apply the overlay dict to the result dict in place.
    """
    if not overlay:
        return

    # Sort the keys according to the rules
    sorted_keys = sorted(overlay.keys(), key=_key_sort_key)

    for key in sorted_keys:
        sigil_type, base_key = _classify_key(key)
        overlay_value = overlay[key]

        if sigil_type == 'remove':
            # Remove base_key from result, no-op if not present
            result.pop(base_key, None)

        elif sigil_type == 'set_if_absent':
            # Set base_key to overlay_value only if base_key not in result
            if base_key not in result:
                result[base_key] = overlay_value

        elif sigil_type == 'prepend':
            # Prepend overlay_value (must be a list) to the list under base_key
            if not isinstance(overlay_value, list):
                raise TypeError(f"Value for prepend key '{key}' must be a list")
            if base_key in result:
                existing = result[base_key]
                if not isinstance(existing, list):
                    raise TypeError(f"Key '{base_key}' in result holds something that is not a list, cannot prepend")
                result[base_key] = overlay_value + existing
            else:
                result[base_key] = list(overlay_value)

        elif sigil_type == 'append':
            # Append overlay_value (must be a list) to the list under base_key
            if not isinstance(overlay_value, list):
                raise TypeError(f"Value for append key '{key}' must be a list")
            if base_key in result:
                existing = result[base_key]
                if not isinstance(existing, list):
                    raise TypeError(f"Key '{base_key}' in result holds something that is not a list, cannot append")
                result[base_key] = existing + overlay_value
            else:
                result[base_key] = list(overlay_value)

        elif sigil_type == 'plain':
            # Plain set or recursive merge
            if base_key in result:
                existing = result[base_key]
                if isinstance(existing, dict) and isinstance(overlay_value, dict):
                    # Recursive merge
                    _apply_overlay(existing, overlay_value)
                elif isinstance(existing, dict) != isinstance(overlay_value, dict):
                    # Exactly one is a dict -> TypeError
                    raise TypeError(f"Cannot merge: key '{base_key}' has dict value on one side but not the other")
                else:
                    # Simple replacement
                    result[base_key] = overlay_value
            else:
                # Key not in result, just set it
                result[base_key] = overlay_value
