import copy

def merge(base, overlay):
    # Deep copy base to ensure no mutation
    result = copy.deepcopy(base)

    if not overlay:
        return result

    # Define priority for keys that resolve to the same base name
    # Order: remove (!), set-if-absent (~), prepend (+k), append (k+), plain set (k)
    PRIORITY = {'!': 0, '~': 1, 'pre': 2, 'app': 3, 'plain': 4}

    def parse_key(k):
        if k.startswith('!'):
            return k[1:], '!', PRIORITY['!']
        if k.startswith('~'):
            return k[1:], '~', PRIORITY['~']
        if k.startswith('+'):
            return k[1:], 'pre', PRIORITY['pre']
        if k.endswith('+'):
            return k[:-1], 'app', PRIORITY['app']
        return k, 'plain', PRIORITY['plain']

    # Sort keys by base name, then by priority
    sorted_keys = sorted(
        overlay.keys(), 
        key=lambda k: (parse_key(k)[0], parse_key(k)[2])
    )

    for k in sorted_keys:
        base_name, op, _ = parse_key(k)
        val = overlay[k]

        if op == '!':
            result.pop(base_name, None)

        elif op == '~':
            if base_name not in result:
                result[base_name] = copy.deepcopy(val)

        elif op == 'pre':
            if not isinstance(val, list):
                raise TypeError(f"Value for {k} must be a list")
            current = result.get(base_name, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {base_name} must be a list for prepending")
            result[base_name] = copy.deepcopy(val) + copy.deepcopy(current)

        elif op == 'app':
            if not isinstance(val, list):
                raise TypeError(f"Value for {k} must be a list")
            current = result.get(base_name, [])
            if not isinstance(current, list):
                raise TypeError(f"Value under {base_name} must be a list for appending")
            result[base_name] = copy.deepcopy(current) + copy.deepcopy(val)

        else: # plain set
            if base_name in result:
                res_val = result[base_name]
                if isinstance(res_val, dict) and isinstance(val, dict):
                    result[base_name] = merge(res_val, val)
                elif not isinstance(res_val, dict) and not isinstance(val, dict):
                    result[base_name] = copy.deepcopy(val)
                else:
                    raise TypeError(f"Type mismatch for key {base_name}: one is dict, other is not")
            else:
                result[base_name] = copy.deepcopy(val)

