def parse_config(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    section_parents: dict[str, str | None] = {}
    current_section: str = 'DEFAULT'

    # Initialize DEFAULT section
    sections['DEFAULT'] = {}
    section_parents['DEFAULT'] = None

    for line in text.splitlines():
        stripped = line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Skip comments
        if stripped.startswith('#'):
            continue

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            inner = stripped[1:-1]
            if ':' in inner:
                name_part, parent_part = inner.split(':', 1)
                name = name_part.strip()
                parent = parent_part.strip()
            else:
                name = inner.strip()
                parent = None

            # Check if parent exists (must be defined earlier)
            if parent is not None:
                if parent not in sections:
                    raise ValueError(f"Parent section '{parent}' not defined before section '{name}'")

            sections[name] = {}
            section_parents[name] = parent
            current_section = name
        else:
            # Key-value line
            if '=' in stripped:
                key_part, value_part = stripped.split('=', 1)
                key = key_part.strip().lower()
                value = value_part.strip()
                sections[current_section][key] = value
            # Lines without '=' that aren't section headers or comments are ignored

    # Resolve inheritance
    def resolve_section(name: str, visited: set[str] | None = None) -> dict[str, str]:
        if visited is None:
            visited = set()
        if name in visited:
            raise ValueError(f"Circular inheritance detected involving section '{name}'")
        visited.add(name)

        # Start with DEFAULT
        result = dict(sections['DEFAULT'])

        # Apply parent chain (transitive)
        parent = section_parents.get(name)
        if parent is not None and parent != 'DEFAULT':
            parent_keys = resolve_section(parent, visited)
            result.update(parent_keys)

        # Apply own keys
        result.update(sections[name])

        return result

    # Build final result with all inheritance resolved
    final_result: dict[str, dict[str, str]] = {}
    for section_name in sections:
        final_result[section_name] = resolve_section(section_name)

    return final_result
