import copy


def merge(base, overlay):
    """Merge a configuration dict `base` with an overlay dict `overlay`.

    Returns a new dict combining base with overlay. Neither argument is mutated.
    """
    if not isinstance(base, dict):
        raise TypeError("base must be a dict")
    if not isinstance(overlay, dict):
        raise TypeError("overlay must be a dict")

    result = copy.deepcopy(base)

    # Parse overlay keys into (name, sigil) pairs
    # Sigils: ! (remove), ~ (set-if-absent), + (prepend), + (append)
    # Order of application for same name: remove, set-if-absent, prepend, append, plain set

    def parse_key(key):
        """Parse a key into (name, sigil) where sigil is one of: 'remove', 'set_if_absent', 'prepend', 'append', 'plain'"""
        if not isinstance(key, str):
            return (key, 'plain')

        # Check for sigils
        # !key -> remove
        if key.startswith('!'):
            return (key[1:], 'remove')
        # ~key -> set-if-absent
        if key.startswith('~'):
            return (key[1:], 'set_if_absent')
        # +key -> prepend
        if key.startswith('+'):
            return (key[1:], 'prepend')
        # key+ -> append
        if key.endswith('+') and len(key) > 1:
            return (key[:-1], 'append')

        return (key, 'plain')

    # Group overlay entries by name, preserving sigil order
    # For each name, collect all sigils in order of application: remove, set_if_absent, prepend, append, plain
    sigil_order = {'remove': 0, 'set_if_absent': 1, 'prepend': 2, 'append': 3, 'plain': 4}

    # Build a list of (name, sigil, value) tuples
    entries = []
    for key, value in overlay.items():
        name, sigil = parse_key(key)
        entries.append((name, sigil, value))

    # Sort by name, then by sigil order
    def sort_key(entry):
        name, sigil, value = entry
        # Use a stable sort: first by name, then by sigil order
        return (name, sigil_order.get(sigil, 4))

    entries.sort(key=sort_key)

    # Apply each entry to result
    for name, sigil, value in entries:
        if sigil == 'remove':
            # Remove key from result; no-op if not present
            if name in result:
                del result[name]

        elif sigil == 'set_if_absent':
            # Set key to value only if key is not in result
            if name not in result:
                result[name] = value

        elif sigil == 'prepend':
            # Prepend value (must be a list) to list under name
            if not isinstance(value, list):
                raise TypeError(f"Value for prepend key '{name}' must be a list")
            if name in result:
                if not isinstance(result[name], list):
                    raise TypeError(f"Key '{name}' in result must hold a list for prepend")
                result[name] = value + result[name]
            else:
                result[name] = list(value)

        elif sigil == 'append':
            # Append value (must be a list) to list under name
            if not isinstance(value, list):
                raise TypeError(f"Value for append key '{name}' must be a list")
            if name in result:
                if not isinstance(result[name], list):
                    raise TypeError(f"Key '{name}' in result must hold a list for append")
                result[name] = result[name] + value
            else:
                result[name] = list(value)

        elif sigil == 'plain':
            # Plain set: merge recursively if both are dicts, otherwise replace
            if name in result:
                if isinstance(result[name], dict) and isinstance(value, dict):
                    # Recursive merge
                    result[name] = merge(result[name], value)
                elif isinstance(result[name], dict) != isinstance(value, dict):
                    # Exactly one is a dict -> TypeError
                    raise TypeError(f"Cannot merge: key '{name}' has dict in one side and non-dict in the other")
                else:
                    # Neither is a dict, or both are non-dicts: replace
                    result[name] = value
            else:
                # Key not in result: set it
                result[name] = value

    return result
