def search_last_rotated(nums, target):
    if not nums:
        return -1

    left, right = 0, len(nums) - 1
    last_index = -1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            last_index = mid
            # Continue searching to the right to find the last occurrence
            left = mid + 1
        elif nums[left] == nums[mid] == nums[right]:
            # All three are equal, we can't determine which side to go
            # Shrink the search space from both ends
            left += 1
            right -= 1
        elif nums[left] <= nums[mid]:
            # Left half is sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right half is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return last_index
