import copy


def merge(base, overlay):
    """
    Merge a configuration dict `base` with an overlay dict `overlay`.
    Returns a new dict; neither argument is mutated.
    """
    result = copy.deepcopy(base)
    _apply_overlay(result, overlay)
    return result


def _apply_overlay(result, overlay):
    """
    Apply overlay keys to result in the correct order.
    """
    # Parse overlay keys into (base_name, sigil_type, original_key)
    # sigil_type: 'remove' (!key), 'set_if_absent' (~key),
    #             'prepend' (+key), 'append' (key+), 'plain' (key)
    parsed = []
    for key in overlay:
        base_name, sigil = _parse_key(key)
        parsed.append((base_name, sigil, key))

    # Sort by base_name, then by sigil order
    # Order: remove, set_if_absent, prepend, append, plain
    sigil_order = {
        'remove': 0,
        'set_if_absent': 1,
        'prepend': 2,
        'append': 3,
        'plain': 4,
    }
    parsed.sort(key=lambda x: (x[0], sigil_order[x[1]]))

    for base_name, sigil, original_key in parsed:
        value = overlay[original_key]
        if sigil == 'remove':
            # !key: remove key from result
            if base_name in result:
                del result[base_name]
        elif sigil == 'set_if_absent':
            # ~key: set key to value only if key not in result
            if base_name not in result:
                result[base_name] = copy.deepcopy(value)
        elif sigil == 'prepend':
            # +key: prepend value (list) to list under key in result
            if not isinstance(value, list):
                raise TypeError(f"Overlay value for '+{base_name}' must be a list")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Result value for '{base_name}' must be a list for prepend")
                result[base_name] = value + result[base_name]
            else:
                result[base_name] = copy.deepcopy(value)
        elif sigil == 'append':
            # key+: append value (list) to list under key in result
            if not isinstance(value, list):
                raise TypeError(f"Overlay value for '{base_name}+' must be a list")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Result value for '{base_name}' must be a list for append")
                result[base_name] = result[base_name] + value
            else:
                result[base_name] = copy.deepcopy(value)
        else:
            # Plain key
            if base_name in result:
                result_val = result[base_name]
                overlay_val = value
                if isinstance(result_val, dict) and isinstance(overlay_val, dict):
                    # Recursive merge
                    _apply_overlay(result_val, overlay_val)
                elif isinstance(result_val, dict) != isinstance(overlay_val, dict):
                    # Exactly one is a dict
                    raise TypeError(
                        f"Cannot merge: key '{base_name}' has dict in one and non-dict in other"
                    )
                else:
                    # Replace
                    result[base_name] = copy.deepcopy(value)
            else:
                # Key not in result, just set it
                result[base_name] = copy.deepcopy(value)


def _parse_key(key):
    """
    Parse a key to determine its base name and sigil type.
    Returns (base_name, sigil_type).
    """
    # Check for sigils
    # !key: remove
    if key.startswith('!'):
        return key[1:], 'remove'
    # ~key: set if absent
    if key.startswith('~'):
        return key[1:], 'set_if_absent'
    # +key: prepend
    if key.startswith('+'):
        return key[1:], 'prepend'
    # key+: append
    if key.endswith('+'):
        return key[:-1], 'append'
    # Plain key
    return key, 'plain'
