def parse_config(text: str) -> dict[str, dict[str, str]]:
    sections_data = {}
    sections_parents = {}
    current_section = 'DEFAULT'

    # Ensure DEFAULT exists in our tracking
    sections_data[current_section] = {}
    sections_parents[current_section] = None

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if line.startswith('[') and line.endswith(']'):
            header = line[1:-1].strip()
            if ':' in header:
                name, parent = header.split(':', 1)
                name = name.strip()
                parent = parent.strip()
            else:
                name = header
                parent = None

            if parent and parent not in sections_data:
                raise ValueError(f"Parent section '{parent}' must be defined before '{name}'")

            current_section = name
            sections_data[current_section] = {}
            sections_parents[current_section] = parent
        elif '=' in line:
            key, value = line.split('=', 1)
            sections_data[current_section][key.strip().lower()] = value.strip()
        else:
            # Ignore malformed lines that aren't headers, comments, or KV pairs
            continue

    # Resolve inheritance
    resolved = {}

    def get_effective_config(section_name):
        if section_name in resolved:
            return resolved[section_name]

        # Priority (lowest to highest): DEFAULT -> Parent Chain -> Section Own
        # Start with DEFAULT
        config = sections_data.get('DEFAULT', {}).copy()

        # Resolve parent chain
        chain = []
        curr = sections_parents.get(section_name)
        while curr is not None:
            chain.append(curr)
            curr = sections_parents.get(curr)

        # Apply parents from oldest ancestor to immediate parent
        for parent in reversed(chain):
            parent_config = get_effective_config(parent)
            # We only want the parent's specific values and its inherited values, 
            # but the logic is simpler: just merge the resolved parent config.
            config.update(parent_config)

        # Apply section's own keys
        config.update(sections_data.get(section_name, {}))

        resolved[section_name] = config
        return config

    # Process all sections (including DEFAULT)
    for section in sections_data:
        get_effective_config(section)

    return resolved
