def parse_config(text: str) -> dict[str, dict[str, str]]:
    # First pass: collect raw sections and their order
    raw_sections: dict[str, dict[str, str]] = {}
    section_order: list[str] = []
    current_section = 'DEFAULT'
    raw_sections['DEFAULT'] = {}
    section_order.append('DEFAULT')

    lines = text.splitlines()

    for line in lines:
        stripped = line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Skip comment lines
        if stripped.startswith('#'):
            continue

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            header_content = stripped[1:-1]
            if ':' in header_content:
                parts = header_content.split(':', 1)
                section_name = parts[0].strip()
                parent_name = parts[1].strip()
            else:
                section_name = header_content.strip()
                parent_name = None

            # Initialize the section if not already
            if section_name not in raw_sections:
                raw_sections[section_name] = {}
                section_order.append(section_name)

            # Store parent info temporarily
            raw_sections[section_name]['__parent__'] = parent_name

            current_section = section_name
        else:
            # Key-value line
            if '=' not in stripped:
                continue  # Skip malformed lines

            key, value = stripped.split('=', 1)
            key = key.strip().lower()
            value = value.strip()

            raw_sections[current_section][key] = value

    # Second pass: resolve inheritance
    # We need to process sections in order, ensuring parents are defined before children
    # Build a mapping of section name to parent
    parent_map: dict[str, str | None] = {}
    for section_name in section_order:
        if section_name == 'DEFAULT':
            parent_map[section_name] = None
        else:
            parent = raw_sections[section_name].get('__parent__')
            parent_map[section_name] = parent

    # Remove the __parent__ key from raw_sections
    for section_name in raw_sections:
        if '__parent__' in raw_sections[section_name]:
            del raw_sections[section_name]['__parent__']

    # Resolve inheritance
    # We'll compute effective keys for each section
    effective: dict[str, dict[str, str]] = {}

    def get_effective(section_name: str) -> dict[str, str]:
        if section_name in effective:
            return effective[section_name]

        result = {}

        # Start with DEFAULT
        if section_name != 'DEFAULT':
            result.update(get_effective('DEFAULT'))

        # Then parent (if any)
        parent = parent_map.get(section_name)
        if parent is not None:
            if parent not in raw_sections:
                raise ValueError(f"Parent section '{parent}' not found for section '{section_name}'")
            result.update(get_effective(parent))

        # Then the section's own keys
        result.update(raw_sections[section_name])

        effective[section_name] = result
        return result

    for section_name in section_order:
        get_effective(section_name)

    return effective
