    current_section = "DEFAULT"
    last_key = None
    last_indent = 0

    for line in text.splitlines():
        stripped_line = line.strip()
        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            continue

        # Check for section header
        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            current_section = stripped_line[1:-1].strip()
            if current_section not in result:
                result[current_section] = {}
            last_key = None
            last_indent = 0
            continue

        # Determine indentation of the current line
        indent = len(line) - len(line.lstrip())

        # Check for key-value separator
        sep_idx_eq = line.find('=')
        sep_idx_col = line.find(':')

        # Find the first occurring separator
        if sep_idx_eq == -1:
            sep_idx = sep_idx_col
        elif sep_idx_col == -1:
            sep_idx = sep_idx_eq
        else:
            sep_idx = min(sep_idx_eq, sep_idx_col)

        if sep_idx != -1:
            # It's a new key-value pair
            key = line[:sep_idx].strip().lower()
            value = line[sep_idx + 1:].strip()

            if current_section not in result:
                result[current_section] = {}

            result[current_section][key] = value
            last_key = key
            last_indent = indent
        else:
            # No separator: check if it's a continuation
            if last_key is not None and indent > last_indent:
                if current_section not in result:
                    result[current_section] = {}

                current_val = result[current_section].get(last_key, "")
                result[current_section][last_key] = f"{current_val} {stripped_line}"
            else:
                # Line with no separator and not a continuation is ignored or 
                # treated as a key with no value (not specified, but usually ignored)
                last_key = None
                last_indent = 0

    # Ensure DEFAULT exists if keys were found before any section
    if "DEFAULT" not in result and not result:
        # This handles the case of an empty file or only comments
        pass 
    elif "DEFAULT" not in result:
        # If we had keys before any section, they are already in result["DEFAULT"]
        # because current_section starts as "DEFAULT".
        pass

    # Ensure any section encountered is present even if empty
    # (Handled by the section header logic)

    # Special case: if keys were added to DEFAULT before any section header, 
    # result["DEFAULT"] will already exist.

    return result
