import copy


def merge(base, overlay):
    """Merge a configuration dict base with an overlay dict overlay.

    Returns a new dict combining base with overlay. Neither argument is mutated.
    """
    result = copy.deepcopy(base)
    _apply_overlay(result, overlay)
    return result


def _apply_overlay(result, overlay):
    """Apply overlay rules to result in place."""
    if not overlay:
        return

    # Parse keys into (base_name, sigil_type)
    # sigil_type: 'plain', 'remove', 'set_if_absent', 'prepend', 'append'
    parsed = []
    for key in overlay:
        base_name, sigil = _parse_key(key)
        parsed.append((base_name, sigil, key))

    # Sort by base_name, then by sigil order: remove(0), set_if_absent(1), prepend(2), append(3), plain(4)
    sigil_order = {'remove': 0, 'set_if_absent': 1, 'prepend': 2, 'append': 3, 'plain': 4}
    parsed.sort(key=lambda x: (x[0], sigil_order[x[1]]))

    for base_name, sigil, original_key in parsed:
        value = overlay[original_key]
        if sigil == 'remove':
            result.pop(base_name, None)
        elif sigil == 'set_if_absent':
            if base_name not in result:
                result[base_name] = value
        elif sigil == 'prepend':
            if not isinstance(value, list):
                raise TypeError(f"Value for prepend key '{original_key}' must be a list")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Key '{base_name}' in result is not a list, cannot prepend")
                result[base_name] = value + result[base_name]
            else:
                result[base_name] = list(value)
        elif sigil == 'append':
            if not isinstance(value, list):
                raise TypeError(f"Value for append key '{original_key}' must be a list")
            if base_name in result:
                if not isinstance(result[base_name], list):
                    raise TypeError(f"Key '{base_name}' in result is not a list, cannot append")
                result[base_name] = result[base_name] + value
            else:
                result[base_name] = list(value)
        else:  # plain
            if base_name in result:
                result_val = result[base_name]
                if isinstance(result_val, dict) and isinstance(value, dict):
                    _apply_overlay(result_val, value)
                elif isinstance(result_val, dict) != isinstance(value, dict):
                    raise TypeError(f"Cannot merge dict with non-dict for key '{base_name}'")
                else:
                    result[base_name] = value
            else:
                result[base_name] = value


def _parse_key(key):
    """Parse a key to extract base name and sigil type.

    Returns (base_name, sigil_type) where sigil_type is one of:
    'plain', 'remove', 'set_if_absent', 'prepend', 'append'

    Sigils:
    - '!' as first char: remove
    - '~' as first char: set_if_absent
    - '+' as first char: prepend
    - '+' as last char: append
    - Otherwise: plain
    """
    if key.startswith('!'):
        return key[1:], 'remove'
    elif key.startswith('~'):
        return key[1:], 'set_if_absent'
    elif key.startswith('+'):
        return key[1:], 'prepend'
    elif key.endswith('+') and len(key) > 1:
        return key[:-1], 'append'
    else:
        return key, 'plain'
