def parse_config(text: str) -> dict[str, dict[str, str]]:
    # First pass: collect raw sections and their order
    raw_sections: dict[str, dict[str, str]] = {}
    section_order: list[str] = []
    current_section = 'DEFAULT'
    raw_sections['DEFAULT'] = {}
    section_order.append('DEFAULT')

    lines = text.splitlines()

    for line in lines:
        stripped = line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Skip comment lines
        if stripped.startswith('#'):
            continue

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            header_content = stripped[1:-1]
            if ':' in header_content:
                parts = header_content.split(':', 1)
                section_name = parts[0].strip()
                parent_name = parts[1].strip()
            else:
                section_name = header_content.strip()
                parent_name = None

            # Check if section already exists
            if section_name in raw_sections:
                # If it's a new definition, we might need to handle this,
                # but typically we just continue adding to it
                pass
            else:
                raw_sections[section_name] = {}
                section_order.append(section_name)

            # Store parent info temporarily
            if parent_name is not None:
                raw_sections[section_name]['__parent__'] = parent_name
            else:
                raw_sections[section_name]['__parent__'] = None

            current_section = section_name
        else:
            # Key-value line
            if '=' not in stripped:
                # Skip lines that don't have '='
                continue

            key, value = stripped.split('=', 1)
            key = key.strip().lower()
            value = value.strip()

            raw_sections[current_section][key] = value

    # Second pass: resolve inheritance
    # We need to process sections in order, ensuring parents are resolved first
    resolved: dict[str, dict[str, str]] = {}

    # First, resolve DEFAULT
    default_keys = {k: v for k, v in raw_sections['DEFAULT'].items() if k != '__parent__'}
    resolved['DEFAULT'] = default_keys

    # Process other sections in order
    for section_name in section_order:
        if section_name == 'DEFAULT':
            continue

        raw = raw_sections[section_name]
        parent_name = raw.get('__parent__')

        # Start with DEFAULT keys
        effective = dict(resolved['DEFAULT'])

        # If there's a parent, inherit from it
        if parent_name is not None:
            if parent_name not in resolved:
                # Parent might not be resolved yet if it appears later,
                # but the spec says parent must be defined earlier
                raise ValueError(f"Parent section '{parent_name}' not found for section '{section_name}'")
            # Inherit from parent (which already includes DEFAULT and its own parents)
            effective.update(resolved[parent_name])

        # Add this section's own keys (excluding __parent__)
        for k, v in raw.items():
            if k != '__parent__':
                effective[k] = v

        resolved[section_name] = effective

    return resolved
