def search_last_rotated(nums, target):
    if not nums:
        return -1

    left, right = 0, len(nums) - 1
    last_index = -1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            last_index = mid
            # Continue searching to the right to find the last occurrence
            left = mid + 1
        elif nums[mid] < target:
            # Determine which half is sorted
            if nums[left] <= nums[mid]:
                # Left half is sorted
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # Right half is sorted
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1
        else:  # nums[mid] > target
            # Determine which half is sorted
            if nums[left] <= nums[mid]:
                # Left half is sorted
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
            else:
                # Right half is sorted
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1

    return last_index
