import re

UNITS = {
    'w': 604800000,
    'd': 86400000,
    'h': 3600000,
    'm': 60000,
    's': 1000,
    'ms': 1,
}

UNIT_ORDER = ['w', 'd', 'h', 'm', 's', 'ms']
UNIT_VALUES = {u: v for u, v in UNITS.items()}


def parse(s):
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if s == '':
        raise ValueError("Empty string")
    if any(c.isspace() for c in s):
        raise ValueError("Whitespace not allowed")

    # Check for leading minus
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
        if s == '':
            raise ValueError("Empty after minus")

    # Check for any other minus signs
    if '-' in s:
        raise ValueError("Minus sign only allowed at start")

    # Special case: just digits means seconds
    if re.fullmatch(r'\d+', s):
        ms = int(s) * 1000
        return -ms if negative else ms

    # Parse terms: number followed by unit
    # Units: w, d, h, m, s, ms
    # We need to match from left to right, with units in strictly descending order

    # Build a regex that matches a single term
    # Number: \d+(\.\d+)?
    # Unit: (ms|w|d|h|m|s)

    # We'll parse manually to have more control

    i = 0
    n = len(s)
    terms = []  # list of (value, unit)

    while i < n:
        # Parse number
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == i:
            raise ValueError("Expected digit")

        # Check for decimal point
        has_fraction = False
        if j < n and s[j] == '.':
            has_fraction = True
            j += 1
            if j >= n or not s[j].isdigit():
                raise ValueError("Expected digit after decimal point")
            while j < n and s[j].isdigit():
                j += 1

        num_str = s[i:j]
        i = j

        # Parse unit
        if i >= n:
            raise ValueError("Expected unit")

        # Try to match unit
        unit = None
        if s[i:i+2] == 'ms':
            unit = 'ms'
            i += 2
        elif s[i] in ('w', 'd', 'h', 'm', 's'):
            unit = s[i]
            i += 1
        else:
            raise ValueError("Unknown unit")

        terms.append((num_str, unit, has_fraction))

    if not terms:
        raise ValueError("No terms")

    # Validate: units must be in strictly descending order, no duplicates
    seen_units = []
    for _, unit, _ in terms:
        if unit in seen_units:
            raise ValueError("Duplicate unit")
        seen_units.append(unit)

    # Check strictly descending order
    for k in range(len(seen_units) - 1):
        if UNIT_ORDER.index(seen_units[k]) >= UNIT_ORDER.index(seen_units[k + 1]):
            raise ValueError("Units not in strictly descending order")

    # Only the smallest unit (last term) may have a fractional part
    for k in range(len(terms) - 1):
        if terms[k][2]:
            raise ValueError("Fractional part only allowed on smallest unit")

    # Calculate total milliseconds
    total_ms = 0.0
    for num_str, unit, _ in terms:
        val = float(num_str)
        total_ms += val * UNIT_VALUES[unit]

    # Truncate toward zero
    if total_ms >= 0:
        result = int(total_ms)
    else:
        result = -int(-total_ms)

    return -result if negative else result


def render(ms):
    if not isinstance(ms, int):
        raise ValueError("Input must be an integer")

    if ms == 0:
        return "0s"

    negative = ms < 0
    ms = abs(ms)

    parts = []
    remaining = ms

    for unit in UNIT_ORDER:
        val = UNIT_VALUES[unit]
        if remaining >= val:
            count = remaining // val
            remaining -= count * val
            if count > 0:
                parts.append(f"{count}{unit}")

    if not parts:
        return "0s"

    result = ''.join(parts)
    return '-' + result if negative else result
