def run(program, max_steps):
    regs = [0] * 4
    flag = 0
    pc = 0
    steps = 0
    MOD = 2**64

    def get_val(op):
        if isinstance(op, str) and op.startswith('#'):
            return int(op[1:])
        if isinstance(op, str) and op.startswith('r'):
            return regs[int(op[1])]
        return op # Should not happen based on spec

    def get_reg_idx(op):
        return int(op[1])

    while True:
        # Check if PC is out of range before fetching
        if pc < 0 or pc >= len(program):
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "fell_off"}

        # Check if step limit reached before fetching
        if steps >= max_steps:
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "step_limit"}

        instr = program[pc]
        opcode = instr[0]

        # Execute instruction
        if opcode == "SET":
            dst = get_reg_idx(instr[1])
            regs[dst] = get_val(instr[2]) % MOD
            pc += 1
        elif opcode == "ADD":
            dst = get_reg_idx(instr[1])
            regs[dst] = (regs[dst] + get_val(instr[2])) % MOD
            pc += 1
        elif opcode == "SUB":
            dst = get_reg_idx(instr[1])
            regs[dst] = (regs[dst] - get_val(instr[2])) % MOD
            pc += 1
        elif opcode == "MUL":
            dst = get_reg_idx(instr[1])
            regs[dst] = (regs[dst] * get_val(instr[2])) % MOD
            pc += 1
        elif opcode == "CMP":
            val_a = get_val(instr[1])
            val_b = get_val(instr[2])
            flag = 1 if val_a < val_b else 0
            pc += 1
        elif opcode == "JMP":
            off = instr[1]
            target = pc + off
            steps += 1
            if target < 0 or target >= len(program):
                return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
            pc = target
            continue # Skip the steps += 1 at the bottom
        elif opcode == "JIF":
            off = instr[1]
            if flag == 1:
                target = pc + off
                steps += 1
                if target < 0 or target >= len(program):
                    return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "bad_jump"}
                pc = target
                continue # Skip the steps += 1 at the bottom
            else:
                pc += 1
        elif opcode == "ROT":
            regs = [regs[1], regs[2], regs[3], regs[0]]
            pc += 1
        elif opcode == "HALT":
            steps += 1
            return {"regs": regs, "flag": flag, "pc": pc, "steps": steps, "reason": "halt"}

        steps += 1
