def parse_config(text: str) -> dict[str, dict[str, str]]:
    # First pass: collect raw sections (without inheritance resolution)
    raw_sections: dict[str, dict[str, str]] = {}
    section_parents: dict[str, str | None] = {}

    current_section = 'DEFAULT'
    raw_sections['DEFAULT'] = {}
    section_parents['DEFAULT'] = None

    for line in text.splitlines():
        stripped = line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Skip comments
        if stripped.startswith('#'):
            continue

        # Check for section header
        if stripped.startswith('[') and stripped.endswith(']'):
            inner = stripped[1:-1]
            if ':' in inner:
                name_part, parent_part = inner.split(':', 1)
                name = name_part.strip()
                parent = parent_part.strip()
            else:
                name = inner.strip()
                parent = None

            current_section = name
            if name not in raw_sections:
                raw_sections[name] = {}
                section_parents[name] = parent
            else:
                # If section already defined, update parent (shouldn't normally happen)
                section_parents[name] = parent
            continue

        # Check for key-value line
        if '=' in stripped:
            key_part, value_part = stripped.split('=', 1)
            key = key_part.strip().lower()
            value = value_part.strip()

            if current_section not in raw_sections:
                raw_sections[current_section] = {}

            raw_sections[current_section][key] = value
            continue

        # Lines that don't match any pattern are ignored

    # Second pass: resolve inheritance
    def resolve_section(name: str, visited: set[str] | None = None) -> dict[str, str]:
        if visited is None:
            visited = set()

        if name in visited:
            raise ValueError(f"Circular inheritance detected involving section '{name}'")

        visited.add(name)

        # Start with DEFAULT
        result = dict(raw_sections.get('DEFAULT', {}))

        # Build the chain of parents
        chain = []
        current = name
        while current is not None and current != 'DEFAULT':
            if current not in raw_sections:
                raise ValueError(f"Section '{current}' not found")
            chain.append(current)
            parent = section_parents.get(current)
            if parent is not None:
                if parent not in raw_sections:
                    raise ValueError(f"Parent section '{parent}' of section '{current}' not found")
                current = parent
            else:
                current = None

        # Apply inheritance in order: DEFAULT (already applied), then parents from root to child
        # chain is [name, parent, grandparent, ...] so we reverse it
        for section_name in reversed(chain):
            result.update(raw_sections.get(section_name, {}))

        return result

    # Resolve all sections
    result: dict[str, dict[str, str]] = {}
    for section_name in raw_sections:
        result[section_name] = resolve_section(section_name)

    return result
